fn production_process_resource_port(
    state: &ServerState,
    request: &Value,
    execution_ref: &ResourceRef,
) -> RoutedProcessResourcePort {
    let resource_ref = process_resource_ref(request);
    if resource_ref.is_none() && request.get("method").and_then(Value::as_str) != Some("List") {
        return RoutedProcessResourcePort(None);
    }
    let Some(zone) = request
        .get("zoneRef")
        .and_then(Value::as_str)
        .and_then(|value| value.strip_prefix("Zone/"))
        .and_then(|value| ZoneId::parse(value.to_owned()).ok())
    else {
        return RoutedProcessResourcePort(None);
    };
    let Some(client) = state
        .resource_plane
        .try_lock()
        .ok()
        .and_then(|plane| plane.clone())
        .and_then(|plane| plane.zone(&zone).ok())
        .and_then(|runtime| runtime.process_resource_client())
    else {
        return RoutedProcessResourcePort(None);
    };
    let Some(driver) = production_component_session_driver_for_service(
        state,
        interaction_composition::PROCESS_ATTACH_SERVICE,
        execution_ref,
    ) else {
        return RoutedProcessResourcePort(None);
    };
    let template = request
        .get("template")
        .and_then(Value::as_str)
        .unwrap_or("shell-terminal")
        .to_owned();
    if d2b_contracts_resource::v3::execution_policy::BoundedToken::parse(&template).is_err() {
        return RoutedProcessResourcePort(None);
    }
    let domain = request
        .get("domain")
        .and_then(Value::as_str)
        .unwrap_or("user")
        .to_owned();
    if !matches!(domain.as_str(), "system" | "user") {
        return RoutedProcessResourcePort(None);
    }
    let requested_user_ref = request
        .get("userRef")
        .and_then(Value::as_str)
        .map(ToOwned::to_owned);
    let needs_execution_spec = matches!(
        request.get("method").and_then(Value::as_str),
        Some("Create" | "Attach")
    );
    let user_ref = if domain == "user" {
        let trusted_user_ref = resolve_process_user_ref(state, execution_ref);
        if requested_user_ref
            .as_deref()
            .is_some_and(|requested| Some(requested) != trusted_user_ref.as_deref())
        {
            return RoutedProcessResourcePort(None);
        }
        trusted_user_ref
    } else {
        requested_user_ref
    };
    if domain == "user" && needs_execution_spec && user_ref.is_none() {
        return RoutedProcessResourcePort(None);
    }
    if let Some(user_ref) = user_ref.as_deref()
        && ResourceRef::parse(user_ref)
            .ok()
            .is_none_or(|value| value.resource_type().as_str() != "User")
    {
        return RoutedProcessResourcePort(None);
    }
    RoutedProcessResourcePort(Some(ComponentSessionProcessResourcePort {
        client,
        driver,
        zone,
        execution_ref: execution_ref.clone(),
        resource_ref,
        domain,
        user_ref,
        template,
        allow_create: request.get("method").and_then(Value::as_str) != Some("Attach"),
    }))
}

fn resolve_process_user_ref(state: &ServerState, execution_ref: &ResourceRef) -> Option<String> {
    if execution_ref.resource_type().as_str() != "Guest" {
        return None;
    }
    let manifest = load_manifest(&state.config.artifacts.public_manifest_path).ok()?;
    let user = manifest
        .get(execution_ref.name().as_str())?
        .get("sshUser")
        .and_then(Value::as_str)?;
    ResourceRef::parse(&format!("User/{user}"))
        .ok()
        .map(|value| value.to_canonical_string())
}

fn production_component_session_driver(
    state: &ServerState,
    target: &str,
) -> Option<d2b_session::SessionDriverHandle> {
    let target = ResourceRef::parse(&format!("Guest/{target}")).ok()?;
    production_component_session_driver_for_service(
        state,
        interaction_composition::SHELL_SESSION_SERVICE,
        &target,
    )
}

fn production_component_session_driver_for_service(
    state: &ServerState,
    service: &str,
    target: &ResourceRef,
) -> Option<d2b_session::SessionDriverHandle> {
    interaction_composition::blocking_component_session_driver_for_service(
        &state.interaction_runtime,
        service,
        target,
    )
}

fn resource_error_to_establish(
    error: &resource_wire::ResourceError,
) -> exec_session::ExecEstablishError {
    match error.kind.enum_value().ok() {
        Some(resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_AUTHORIZATION_DENIED) => {
            exec_session::ExecEstablishError::Auth
        }
        Some(
            resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_PROVIDER_UNAVAILABLE
            | resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_PLANE_UNAVAILABLE
            | resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_TIMEOUT
            | resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_BACKPRESSURE,
        ) => exec_session::ExecEstablishError::Transport,
        Some(
            resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_UNSUPPORTED_CAPABILITY
            | resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_NOT_FOUND
            | resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_ALREADY_EXISTS
            | resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_CONFLICT,
        ) => exec_session::ExecEstablishError::Capability,
        _ => exec_session::ExecEstablishError::Protocol,
    }
}

fn resource_error_to_op(error: &resource_wire::ResourceError) -> exec_session::ExecOpError {
    match resource_error_to_establish(error) {
        exec_session::ExecEstablishError::Transport => exec_session::ExecOpError::Transport,
        exec_session::ExecEstablishError::Auth => exec_session::ExecOpError::Auth,
        exec_session::ExecEstablishError::Capability => exec_session::ExecOpError::Capability,
        exec_session::ExecEstablishError::Protocol => exec_session::ExecOpError::Protocol,
        exec_session::ExecEstablishError::Timeout => exec_session::ExecOpError::Timeout,
        exec_session::ExecEstablishError::OldGeneration => exec_session::ExecOpError::OldGeneration,
        exec_session::ExecEstablishError::Guest(error) => exec_session::ExecOpError::Guest(error),
    }
}

fn detached_status_from_resource(
    bytes: &[u8],
) -> Result<public_wire::ExecDetachedStatusResult, ()> {
    let envelope =
        d2b_contracts_resource::v3::ResourceEnvelope::from_json(bytes).map_err(|_| ())?;
    if envelope.resource_type().as_str() != "EphemeralProcess" {
        return Err(());
    }
    let value: Value = serde_json::from_slice(bytes).map_err(|_| ())?;
    let phase = value
        .pointer("/status/phase")
        .and_then(Value::as_str)
        .ok_or(())?;
    let state = match phase {
        "Pending" | "Ready" | "Degraded" => d2b_contracts_control::public_wire::ExecState::Running,
        "Succeeded" | "Deleted" => d2b_contracts_control::public_wire::ExecState::Exited,
        "Failed" => d2b_contracts_control::public_wire::ExecState::ProtocolError,
        _ => d2b_contracts_control::public_wire::ExecState::ProtocolError,
    };
    let reason = value
        .pointer("/status/outcome/code")
        .and_then(Value::as_str)
        .map(ToOwned::to_owned);
    Ok(public_wire::ExecDetachedStatusResult {
        exec_id: envelope.metadata().name().as_str().to_owned(),
        state,
        reason,
        exit_code: None,
        signal: None,
        start_offset: 0,
        end_offset: 0,
        dropped_bytes: 0,
        truncated: false,
    })
}

fn next_component_session_stream_number() -> u16 {
    u16::try_from(next_internal_process_stream_id() % u64::from(u16::MAX))
        .unwrap_or(1)
        .max(1)
}

fn next_internal_process_stream_id() -> u64 {
    static STREAM_ID: AtomicU64 = AtomicU64::new(1);
    loop {
        let value = STREAM_ID.fetch_add(1, Ordering::Relaxed);
        if value != 0 {
            return value;
        }
    }
}

fn admission_config(state: &ServerState) -> AdmissionConfig {
    AdmissionConfig {
        daemon_uid: state.daemon_uid,
        public_socket_group: state.config.public_socket_group.clone(),
        launcher_users: state.config.launcher_users.clone(),
        admin_users: state.config.admin_users.clone(),
    }
}

/// Load the daemon config, apply CLI overrides, bind the operator socket,
/// and run the accept loop until a shutdown signal lands. The daemon's
/// startup contracts (pidfs support, state-lock parent, operator socket
/// posture) are enforced before any socket is served. Operator tooling
/// uses `lock_only` to hold the state lock without starting the daemon.
///
/// # Errors
///
/// Returns [`TypedError`] for config-load and override failures, invalid
/// startup-contract state (pidfs, state lock, socket path), IO failures
/// (socket bind, helper socket, pidfd-table restore), and caller
/// authorization refusals during the accept loop.
pub async fn serve(options: ServeOptions) -> Result<(), TypedError> {
    let mut config = load_config(&options.config_path)?;
    apply_overrides(&mut config, &options);
    let notify_socket = std::env::var_os("NOTIFY_SOCKET");

    // v1.1.1 runtime pidfs self-probe: refuse startup on kernels
    // without pidfs support. Static `tests/v1.1-kernel-floor-eval.sh`
    // catches the easy case (operator flake declares < 6.9 kernel);
    // this probe catches the hard case (custom-built kernel at >= 6.9
    // that strips CONFIG_FS_PID). Soft-fail opt-in via the
    // `D2B_ALLOW_PIDFS_PROBE_SOFT_FAIL` env var (CI/dev hosts).
    {
        let outcome = d2bd_runtime::pidfs_probe::probe_pidfs();
        d2bd_runtime::pidfs_probe::enforce_probe_outcome(&outcome)?;
    }

    let runtime_identity =
        resolve_runtime_identity(&config, options.allow_unprivileged_runtime_dir)?;
    validate_lock_parent(&config.state_lock_path, &runtime_identity)?;
    ensure_locks_dir(&config.locks_dir, &runtime_identity)?;
    let _lock_file = acquire_state_lock(&config.state_lock_path, &runtime_identity)?;
    let listener = bind_public_socket(&config.public_socket_path, &runtime_identity)?;
    let mut sigterm = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
        .map_err(|error| TypedError::InternalIo {
            context: "install SIGTERM shutdown handler".to_owned(),
            detail: error.to_string(),
            source: error_source(error),
        })?;
    let mut sigint = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::interrupt())
        .map_err(|error| TypedError::InternalIo {
            context: "install SIGINT shutdown handler".to_owned(),
            detail: error.to_string(),
            source: error_source(error),
        })?;
    let unsafe_local_helper_uids =
        resolve_unsafe_local_helper_uids(&config, runtime_identity.daemon_uid)?;
    let unsafe_local_helper_listener =
        if let Some(path) = config.unsafe_local_helper_socket_path.as_deref() {
            let socket_gid = runtime_identity
                .unsafe_local_helper_socket_gid
                .ok_or_else(|| TypedError::InternalConfig {
                    detail: "unsafe-local helper socket path requires a socket group".to_owned(),
                    source: None,
                })?;
            Some(
                d2bd_runtime::unsafe_local_helper::bind_helper_socket(
                    path,
                    socket_gid,
                    runtime_identity.expect_root_owned_parent,
                )
                .map_err(|error| TypedError::InternalIo {
                    context: "bind unsafe-local helper socket".to_owned(),
                    detail: format!("{error:?}"),
                    source: None,
                })?,
            )
        } else {
            None
        };

    if options.drop_privileges {
        drop_privileges_if_root(&runtime_identity)?;
    }
    sd_notify_status(
        notify_socket.as_deref(),
        "d2bd public socket bound; restoring state",
    );

    // The forwarding rendezvous: the endpoint the broker dials for every
    // forwarded operation. It binds only when the environment names a path,
    // mirroring the broker's own no-default stance, so a deployment with no
    // forwarding peer binds nothing and both ends refuse forwarded calls.
    let forward_rendezvous =
        std::sync::Arc::new(crate::forward_rendezvous::ForwardRendezvous::new());
    if let Some(path) = crate::forward_rendezvous::configured_socket() {
        let listener = crate::forward_rendezvous::bind(&path, &runtime_identity)?;
        crate::forward_rendezvous::spawn_server(
            std::sync::Arc::clone(&forward_rendezvous),
            listener,
            tokio::runtime::Handle::current(),
        )?;
        tracing::info!(socket = %path.display(), "d2bd forward rendezvous ready");
    }

    // Write /run/d2b/version on daemon startup so the CLI's
    // [pending restart] machinery has
    // an authoritative version + binary-path snapshot. Failures are
    // logged but non-fatal - operators can still drive the daemon
    // without the pending-restart signal.
    write_daemon_version_file(&config);
    maybe_write_state_restore_report(&options)?;

    let daemon_state_dir = effective_daemon_state_dir(&options);
    let pidfd_table_path = pidfd_table_state_path(&daemon_state_dir);
    let broker_reap_log = BrokerReapLog::new();
    let pidfd_table = Arc::new(PidfdTable::restore_from_disk(&pidfd_table_path).map_err(
        |err| TypedError::InternalIo {
            context: format!("restore pidfd table {}", pidfd_table_path.display()),
            detail: err.to_string(),
            source: error_source(err),
        },
    )?);
    pidfd_table.set_broker_reap_log(Arc::clone(&broker_reap_log));
    sd_notify_status(
        notify_socket.as_deref(),
        "d2bd restored runner state; checking startup contracts",
    );

    if let Some(realm_controllers) =
        load_realm_controllers_config(&config.realm_controllers_config_path)?
    {
        tracing::info!(
            config_source = "realm-controllers",
            config_present = true,
            controller_count = realm_controllers.summary.controller_count,
            host_local_controller_count = realm_controllers.summary.host_local_controller_count,
            broker_enabled_count = realm_controllers.summary.broker_enabled_count,
            "realm-controller metadata loaded; runtime routing remains inert",
        );
    } else {
        tracing::debug!(
            config_source = "realm-controllers",
            config_present = false,
            "realm-controller metadata not present; continuing with single-root daemon config",
        );
    }
    if let Some(realm_identity) = load_realm_identity_config(&config.realm_identity_config_path)? {
        tracing::info!(
            config_source = "realm-identity",
            config_present = true,
            realm_count = realm_identity.summary.realm_count,
            identity_ref_count = realm_identity.summary.identity_ref_count,
            controller_credential_ref_count =
                realm_identity.summary.controller_credential_ref_count,
            "realm identity metadata loaded; runtime trust sessions remain inert",
        );
    } else {
        tracing::debug!(
            config_source = "realm-identity",
            config_present = false,
            "realm identity metadata not present; runtime trust sessions remain inert",
        );
    }

    let unsafe_local_helpers = Arc::new(d2bd_runtime::unsafe_local_helper::HelperRegistry::new(
        runtime_identity.daemon_uid.as_raw(),
        unsafe_local_helper_uids,
    ));
    #[cfg(not(test))]
    let resource_plane = Arc::new(tokio::sync::Mutex::new(None));
    let state = ServerState {
        daemon_uid: runtime_identity.daemon_uid.as_raw(),
        config,
        daemon_audit: Arc::new(d2bd_runtime::daemon_audit::DaemonAuditLog::new(
            &daemon_state_dir,
        )),
        daemon_state_dir: daemon_state_dir.clone(),
        pidfd_table,
        broker_reap_log,
        metrics_registry: Arc::new(d2bd_runtime::metrics::Registry::new()),
        exec_sessions: Arc::new(crate::exec_session::SessionTable::new(
            crate::exec_session::ExecSessionCaps::default(),
        )),
        console_sessions: Arc::new(tokio::sync::Mutex::new(
            crate::console_session::ConsoleSessionTable::default(),
        )),
        conn_semaphore: d2bd_runtime::concurrency::ConnSemaphore::new(
            resolve_max_inflight_connections(),
        ),
        op_locks: d2bd_runtime::concurrency::OpLockManager::new(),
        public_status_read_model: Arc::new(
            d2bd_runtime::public_read_model::PublicStatusReadModel::new(),
        ),
        provider_runtime: Arc::new(
            crate::provider_registry::ProviderRuntime::new(),
        ),
        #[cfg(not(test))]
        resource_plane: Arc::clone(&resource_plane),
        #[cfg(test)]
        resource_plane: Arc::new(tokio::sync::Mutex::new(None)),
        #[cfg(not(test))]
        shell_authority: Arc::new(DaemonShellAuthority::new(
            Arc::clone(&resource_plane),
            tokio::runtime::Handle::current(),
        )),
        interaction_runtime: Arc::new(tokio::sync::Mutex::new(None)),
        interaction_listeners: Arc::new(tokio::sync::Mutex::new(None)),
        typed_shell_session_targets: d2bd_runtime::typed_shell_targets::new_cache(),
        zone_coordinator: d2bd_runtime::zone_authority::new_coordinator(),
        config_staging: Arc::new(tokio::sync::Mutex::new(Default::default())),
        guest_component_sessions: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
        guest_component_session_locks: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
        security_key_sessions: Arc::new(tokio::sync::Mutex::new(
            d2b_provider_device_security_key::SkSessionTable::default(),
        )),
        unsafe_local_helpers: Arc::clone(&unsafe_local_helpers),
        v3_planes: std::sync::Arc::new(tokio::sync::Mutex::new(HashMap::new())),
        runtime_handle: tokio::runtime::Handle::current(),
    };
    if let Some(helper_listener) = unsafe_local_helper_listener {
        std::thread::Builder::new()
            .name("d2b-unsafe-local-listener".to_owned())
            .spawn(move || unsafe_local_helpers.accept_loop(helper_listener))
            .map_err(|error| TypedError::InternalIo {
                context: "spawn unsafe-local helper listener".to_owned(),
                detail: error.to_string(),
                source: error_source(error),
            })?;
    }
    refresh_activation_marker_metrics_on_startup(&state).await;
    refresh_broker_reap_log(&state, "startup");

    let mut startup_resource_plane_ready = !state.config.enable_resource_plane;
    match load_bundle_resolver_on_worker(&state).await {
        Ok(resolver) => {
            let provider_root = d2bd_runtime::zone_authority::authoritative_zone_ids(&resolver)
                .ok()
                .and_then(|zones| committed_zone_topology(&resolver, &zones).ok())
                .map(|topology| topology.root);
            let provider_ready = match provider_root.as_ref() {
                Some(_) if resolver.bundle().schema_version == "v3" => {
                    let process_providers =
                        Arc::new(process_provider_runtime::ProductionProcessProviders::new(
                            resolver.clone(),
                            broker_socket_path(&state),
                            BrokerCallerRole::AdminUid {
                                uid: state.daemon_uid,
                            },
                            state.pidfd_table.clone(),
                        ));
                    let process_providers_ready = state
                        .provider_runtime
                        .attach_process_providers(process_providers)
                        .is_ok();
                    if !process_providers_ready {
                        tracing::error!(
                            "Process Provider supervisors could not be attached; Provider lifecycle effects are disabled",
                        );
                    }
                    process_providers_ready
                }
                Some(_) => {
                    tracing::error!(
                        schema = %resolver.bundle().schema_version,
                        "Provider composition refused: only v3 bundles are supported",
                    );
                    false
                }
                None => {
                    tracing::error!(
                        "provider registry refused: committed Zone topology root is unavailable",
                    );
                    false
                }
            };
            if let Err(error) = d2bd_runtime::zone_authority::register_authoritative_zones(
                &state.zone_coordinator,
                &resolver,
            )
            .await
            {
                tracing::error!(
                    error,
                    "trusted bundle did not populate the Zone authority index; Zone coordination will fail closed",
                );
            } else if !state.config.enable_resource_plane {
                tracing::info!(
                    "resource plane disabled by daemon config; skipping Zone runtime publication",
                );
            } else {
                restore_configuration_staging_on_startup(&state).await;
                match open_resource_plane(&state, &resolver, provider_ready, &forward_rendezvous).await
                {
                    Ok(plane) => {
                        for zone in plane.zone_ids() {
                            audit_resource_plane(
                                &state,
                                &zone,
                                d2bd_runtime::daemon_audit::ResourcePlaneAction::Start,
                                d2bd_runtime::daemon_audit::ResourcePlaneResult::Ready,
                            )
                            .await
                            .map_err(|error| {
                                TypedError::InternalIo {
                                    context: "authoritative resource-plane start audit".to_owned(),
                                    detail: error.to_string(),
                                    source: error_source(error),
                                }
                            })?;
                        }
                        {
                            // tokio::sync does not poison (plan U10): the
                            // poison-refusal arm is gone, and the await owns
                            // the guard for the two assignments only.
                            *state.resource_plane.lock().await = Some(Arc::clone(&plane));
                            startup_resource_plane_ready =
                                plane.ready_zone_count() == plane.zone_ids().len();
                        }
                        let mut runtimes = InteractionRuntime::new();
                        let mut listener_set: Option<
                            interaction_composition::InteractionListenerSet,
                        > = None;
                        let mut interaction_required = false;
                        let mut interaction_startup_failed = false;
                        for zone in plane.zone_ids() {
                            let Some(resource) = plane.zone(&zone).ok() else {
                                continue;
                            };
                            if resource.require_ready().is_err() {
                                continue;
                            }
                            match resource.interaction_state() {
                                resource_runtime::InteractionState::Absent => continue,
                                resource_runtime::InteractionState::Refused => {
                                    interaction_required = true;
                                    interaction_startup_failed = true;
                                    tracing::error!(
                                        zone = %zone,
                                        "interaction Provider composition refused: committed configuration is incomplete",
                                    );
                                    continue;
                                }
                                resource_runtime::InteractionState::Ready => {
                                    interaction_required = true;
                                }
                            }
                            match interaction_composition::production_interaction_composition(
                                state.daemon_uid,
                                interaction_composition::ProductionInteractionResourceState::new(
                                    zone.clone(),
                                    resource.committed_policy_snapshot(),
                                    resource.current_revision(),
                                    true,
                                    resource.interaction_provider_configuration(),
                                    resource.interaction_identity(),
                                    resource.process_resource_client(),
                                ),
                            ) {
                                Ok(runtime) => {
                                    runtimes.insert(zone.clone(), runtime);
                                }
                                Err(error) => {
                                    interaction_startup_failed = true;
                                    tracing::error!(
                                        error = ?error,
                                        zone = %zone,
                                        "interaction Provider composition failed closed during startup",
                                    );
                                }
                            }
                        }
                        if !runtimes.is_empty() {
                            let composed_zones = runtimes
                                .zone_names()
                                .map(ToOwned::to_owned)
                                .collect::<Vec<_>>();
                            *state.interaction_runtime.lock().await = Some(runtimes);
                            let shared_stop = Arc::new(std::sync::atomic::AtomicBool::new(false));
                            for zone_name in composed_zones {
                                let Ok(zone) = ZoneId::parse(&zone_name) else {
                                    continue;
                                };
                                match interaction_composition::spawn_interaction_listeners_with_stop(
                                    Arc::clone(&state.interaction_runtime),
                                    state
                                        .daemon_state_dir
                                        .join("interaction")
                                        .join(zone.as_str()),
                                    zone,
                                    state.daemon_uid,
                                    Arc::clone(&shared_stop),
                                )
                                .await
                                {
                                    Ok(listeners) => {
                                        if let Some(existing) = listener_set.as_mut() {
                                            existing.extend(listeners).await;
                                        } else {
                                            listener_set = Some(listeners);
                                        }
                                    }
                                    Err(error) => {
                                        interaction_startup_failed = true;
                                        tracing::error!(
                                            %error,
                                            "interaction Provider listeners failed closed during startup",
                                        );
                                    }
                                }
                            }
                            if let Some(listeners) = listener_set {
                                let paths = listeners.paths().to_owned();
                                *state.interaction_listeners.lock().await = Some(listeners);
                                tracing::info!(
                                    listener_count = paths.len(),
                                    "ComponentSession listeners ready",
                                );
                            }
                        } else if interaction_required {
                            tracing::error!(
                                "interaction Provider composition refused: no ready resource Zone",
                            );
                        }
                        if interaction_startup_failed {
                            startup_resource_plane_ready = false;
                        }
                    }
                    Err(error) => {
                        if let Ok(zones) =
                            d2bd_runtime::zone_authority::authoritative_zone_ids(&resolver)
                        {
                            for zone in zones {
                                record_authoritative_resource_plane_audit(
                                    &state,
                                    &zone,
                                    d2bd_runtime::daemon_audit::ResourcePlaneAction::Start,
                                    d2bd_runtime::daemon_audit::ResourcePlaneResult::Refused,
                                )
                                .await
                                .map_err(|audit_error| {
                                    TypedError::InternalIo {
                                        context: "authoritative resource-plane refusal audit"
                                            .to_owned(),
                                        detail: audit_error.to_string(),
                                        source: error_source(audit_error),
                                    }
                                })?;
                            }
                        }
                        tracing::error!(
                            error = %error,
                            "production Zone resource plane failed to start; no legacy resource fallback is enabled",
                        );
                    }
                }
            }
            let report = storage_lifecycle::run_startup_contract_check(&resolver);
            if report.has_only_legacy_contract_issue() {
                tracing::info!(
                    bundle_version = resolver.bundle().bundle_version,
                    report_kind = "storage-lifecycle",
                    "storage-lifecycle: legacy bundle lacks storage/sync contracts; rebuild host configuration to enable startup contract checks",
                );
            } else if report.is_degraded() {
                let issue_kinds = report.issue_kinds_csv();
                tracing::warn!(
                    issue_count = report.issues.len(),
                    issue_kinds = %issue_kinds,
                    path_count = report.path_count,
                    restart_policy_count = report.restart_policy_count,
                    lock_count = report.lock_count,
                    report_kind = "storage-lifecycle",
                    "storage-lifecycle: startup contract check degraded",
                );
            } else {
                tracing::info!(
                    path_count = report.path_count,
                    restart_policy_count = report.restart_policy_count,
                    lock_count = report.lock_count,
                    report_kind = "storage-lifecycle",
                    "storage-lifecycle: startup contract check clean",
                );
            }
            persist_storage_lifecycle_report(&state.daemon_state_dir, &report);
        }
        Err(error) => {
            let report_path = storage_lifecycle_report_path(&state.daemon_state_dir);
            // Fail closed for doctor/status consumers if the replacement
            // report cannot be written below: stale clean evidence is worse
            // than an absent report.
            // KTD9: the removal is a blocking fs call; the tokio fs driver
            // keeps it off the runtime workers.
            match tokio::fs::remove_file(&report_path).await {
                Ok(()) => {}
                Err(err) if err.kind() == std::io::ErrorKind::NotFound => {}
                Err(err) => {
                    tracing::warn!(
                        error = %err,
                        report_kind = "storage-lifecycle",
                        "storage-lifecycle: remove stale report failed",
                    );
                }
            }
            let report = storage_lifecycle::bundle_resolver_unavailable_report();
            persist_storage_lifecycle_report(&state.daemon_state_dir, &report);
            let issue_kinds = report.issue_kinds_csv();
            tracing::warn!(
                error = %error.message(),
                issue_kinds = %issue_kinds,
                report_kind = "storage-lifecycle",
                "storage-lifecycle: skipped (bundle resolver unavailable)",
            );
        }
    }
    adopt_orphaned_runners_on_startup(&state).await;

    // Startup self-check on the kernel-module matrix the bundle requires.
    // Fatal misses
    // refuse daemon start; optional misses are logged and the
    // affected VMs are skipped (Degraded) by the autostart pass.
    // If the bundle resolver itself is unavailable we skip the
    // gate - the autostart pass already logs and short-circuits
    // in that case, and the daemon must remain reachable for
    // diagnostic verbs (status / doctor / audit).
    let module_degraded_vms: BTreeSet<String> = match load_bundle_resolver_on_worker(&state).await {
        Ok(resolver) => {
            let report = d2bd_runtime::kernel_module_check::run_kernel_module_check(&resolver);
            // D2B_SKIP_KERNEL_MODULE_CHECK converts the fatal check
            // into a logged warning. Real
            // deployments on hosts whose kernel has the GUEST-side
            // virtio modules built in (vs loadable) get false-
            // positives because the check uses `lsmod` and the
            // built-in modules don't appear there. The check
            // remains the default; the env-var is an explicit
            // operator override for the substrate-replaced v1.1
            // hosts where the historical module list is stale.
            let skip_kernel_check = std::env::var_os("D2B_SKIP_KERNEL_MODULE_CHECK").is_some();
            if report.is_fatal() && !skip_kernel_check {
                persist_kernel_module_report(&state.daemon_state_dir, &report);
                let err = d2bd_runtime::kernel_module_check::fatal_typed_error(&report);
                tracing::error!(
                    kind = err.kind(),
                    missing = %report.missing_required_summary(),
                    present = ?report.present,
                    "kernel-module-check: refusing daemon startup; required modules missing",
                );
                return Err(err);
            }
            if report.is_fatal() && skip_kernel_check {
                tracing::warn!(
                    missing = %report.missing_required_summary(),
                    present = ?report.present,
                    "kernel-module-check: fatal misses bypassed via D2B_SKIP_KERNEL_MODULE_CHECK; affected VMs may fail at start",
                );
            }
            for row in &report.optional_missing {
                tracing::warn!(
                    module = %row.module,
                    affected_vms = ?row.affected_vms,
                    reason = %row.reason,
                    "kernel-module-check: optional module missing",
                );
            }
            let degraded = report.degraded_vms();
            persist_kernel_module_report(&state.daemon_state_dir, &report);
            degraded
        }
        Err(error) => {
            tracing::warn!(
                error = %error.message(),
                "kernel-module-check: skipped (bundle resolver unavailable)",
            );
            BTreeSet::new()
        }
    };
    let combined_pre_degraded =
        startup_autostart_pre_degraded_vms(&module_degraded_vms, &BTreeSet::new());

    sd_notify_status(
        notify_socket.as_deref(),
        "d2bd running startup autostart reconciliation",
    );
    run_startup_autostart(&state, &combined_pre_degraded).await;
    if startup_resource_plane_ready {
        sd_notify_ready(notify_socket.as_deref());
    } else {
        sd_notify_status(
            notify_socket.as_deref(),
            "d2bd diagnostic public socket only; resource plane is not ready",
        );
    }
    let interaction_runtime_ready = state.interaction_runtime.lock().await.is_some();
    if startup_resource_plane_ready {
        tracing::info!(
            socket_kind = "public",
            socket_ready = true,
            resource_plane_ready = true,
            interaction_runtime_ready,
            "d2bd public socket ready; accepting connections",
        );
    } else {
        tracing::warn!(
            socket_kind = "public",
            socket_ready = false,
            resource_plane_ready = false,
            interaction_runtime_ready,
            "d2bd public socket bound for diagnostic requests; readiness withheld",
        );
    }

    loop {
        let accepted = tokio::select! {
            _ = sigterm.recv() => {
                finalize_daemon_interactions(&state).await?;
                break;
            }
            _ = sigint.recv() => {
                finalize_daemon_interactions(&state).await?;
                break;
            }
            _ = tokio::time::sleep(Duration::from_millis(10)) => {
                match listener.accept() {
                    Ok(accepted) => Some(accepted),
                    Err(error) if error.kind() == io::ErrorKind::WouldBlock => None,
                    Err(error) => {
                        let accept_error = TypedError::InternalIo {
                            context: "accept public seqpacket client".to_owned(),
                            detail: error.to_string(),
                            source: error_source(error),
                        };
                        if let Err(cleanup_error) = finalize_daemon_interactions(&state).await {
                            tracing::error!(
                                ?cleanup_error,
                                "interaction Provider finalization failed after accept error",
                            );
                        }
                        return Err(accept_error);
                    }
                }
            }
        };
        let Some((stream, _)) = accepted else {
            continue;
        };
        stream
            .set_nonblocking(false)
            .map_err(|error| TypedError::InternalIo {
                context: "set accepted public socket blocking".to_owned(),
                detail: error.to_string(),
                source: error_source(error),
            })?;

        // The `once` test path stays fully synchronous/inline so unit
        // tests can drive a single connection deterministically.
        if options.once {
            if let Err(error) = handle_connection(stream, &state, None) {
                tracing::error!(
                    error = %error.message(),
                    "connection handler failed",
                );
            }
            finalize_daemon_interactions(&state).await?;
            break;
        }

        // Authz-first: resolve SO_PEERCRED immediately after accept, before
        // any blocking frame read, so an unauthorized or silent peer can
        // neither occupy a handler slot nor stall the accept loop.
        let peer = match authorize_peer(&stream, &admission_config(&state)) {
            Ok(peer) => peer,
            Err(error) => {
                let _ = write_json_frame_deadlined(
                    &stream,
                    &d2bd_runtime::wire::hello_rejected(&error),
                    ACCEPT_REFUSAL_WRITE_DEADLINE,
                );
                drain_rejected_peer_input(&stream);
                tracing::error!(
                    error = %error.message(),
                    "public connection authorization refused",
                );
                continue;
            }
        };

        // Non-blocking admission: never block the accept loop. On a cap
        // miss refuse immediately with a typed-busy frame (deadlined).
        let permit = match state.conn_semaphore.try_acquire() {
            Some(permit) => permit,
            None => {
                let busy = TypedError::DaemonBusy;
                let _ = write_json_frame_deadlined(
                    &stream,
                    &d2bd_runtime::wire::error_frame(&busy),
                    ACCEPT_REFUSAL_WRITE_DEADLINE,
                );
                drain_rejected_peer_input(&stream);
                continue;
            }
        };

        // Hand the connection to its own handler thread, moving the RAII
        // permit in so the in-flight slot is released when the handler -
        // not the accept loop - finishes. accept() returns immediately.
        let conn_state = state.clone();
        if let Err(err) = std::thread::Builder::new()
            .name("d2b-conn".to_owned())
            .spawn(move || {
                // `permit` (and, for an exec session, ownership of it) is
                // dropped when this handler returns.

                let peer_uid = peer.uid;
                if let Err(error) =
                    handle_connection_authorized(stream, &conn_state, peer, Some(permit))
                {
                    tracing::error!(
                        peer_uid,
                        error = %error.message(),
                        "connection handler failed",
                    );
                }
            })
        {
            // Spawn failure drops the moved closure (and its permit), so
            // the slot is released; log and keep serving.
            tracing::error!(
                error = %err,
                "connection handler thread spawn failed",
            );
        }
    }

    Ok(())
}

/// Process-start Guest mode options. These options contain only the Guest
/// target identity and its own broker/state roots; Host bundle, public socket,
/// and realm paths are intentionally absent.
#[derive(Debug, Clone)]
pub struct GuestServeOptions {
    pub guest_ref: String,
    pub guest_uid: String,
    pub zone: String,
    pub purpose: String,
    pub schema_fingerprint: String,
    pub reconnect_generation: u64,
    pub provider_generation: u64,
    pub controller_generation: u64,
    pub assignment_epoch: u64,
    pub broker_socket_path: PathBuf,
    pub broker_uid: u32,
    pub state_dir: PathBuf,
    pub bundle_path: PathBuf,
    pub guest_config_path: PathBuf,
    pub boot_id_path: PathBuf,
    pub local_private_key_path: Option<PathBuf>,
    pub parent_public_key_path: Option<PathBuf>,
    /// Guest-local gateway configuration. The file contains only runtime
    /// paths and non-secret Relay coordinates; absence means this Guest is not
    /// a Gateway execution target.
    pub gateway_zone_link_config_path: Option<PathBuf>,
    pub validate_only: bool,
    pub once: bool,
}

/// Guest-local inputs for the selected Azure Relay transport Provider.
#[derive(Debug, Clone)]
pub struct GatewayGuestZoneLinkOptions {
    pub credential_path: PathBuf,
    pub seal_key_path: PathBuf,
    pub observation_path: Option<PathBuf>,
    pub execution_ref: ResourceRef,
    pub network_ref: ResourceRef,
    pub settings: RelayTransportSettings,
    pub max_concurrent_sessions: u32,
    pub connect_timeout_seconds: u32,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct GatewayGuestConfigFile {
    credential_path: PathBuf,
    seal_key_path: PathBuf,
    observation_path: Option<PathBuf>,
    relay: GatewayGuestRelayConfigFile,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct GatewayGuestRelayConfigFile {
    namespace: Option<String>,
    entity: Option<String>,
}

const GATEWAY_GUEST_OPEN_OBSERVATION_PATH: &str = "/run/d2b-gateway-observation/opened";

fn validate_gateway_guest_observation_path(
    path: Option<PathBuf>,
) -> Result<Option<PathBuf>, TypedError> {
    let Some(path) = path else {
        return Ok(None);
    };
    if path != Path::new(GATEWAY_GUEST_OPEN_OBSERVATION_PATH) {
        return Err(TypedError::InternalConfig {
            detail: "Guest gateway observation path is invalid".to_owned(),
            source: None,
        });
    }
    Ok(Some(path))
}

async fn load_gateway_guest_zone_link_options(
    config_path: Option<&Path>,
    identity: &d2bd_runtime::guest_mode::GuestIdentity,
    bundle: &BundleResolver,
) -> Result<Option<GatewayGuestZoneLinkOptions>, TypedError> {
    let Some(config_path) = config_path else {
        return Ok(None);
    };
    let metadata = match tokio::fs::symlink_metadata(config_path).await {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(None),
        Err(_) => {
            return Err(TypedError::InternalConfig {
                detail: "Guest gateway configuration unavailable".to_owned(),
                source: None,
            });
        }
    };
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Err(TypedError::InternalConfig {
            detail: "Guest gateway configuration is not a regular file".to_owned(),
            source: None,
        });
    }
    let bytes = tokio::fs::read(config_path).await.map_err(|_| TypedError::InternalConfig {
        detail: "Guest gateway configuration unavailable".to_owned(),
        source: None,
    })?;
    let config: GatewayGuestConfigFile =
        serde_json::from_slice(&bytes).map_err(|_| TypedError::InternalConfig {
            detail: "Guest gateway configuration is invalid".to_owned(),
            source: None,
        })?;
    let observation_path = validate_gateway_guest_observation_path(config.observation_path)?;
    let namespace = config
        .relay
        .namespace
        .ok_or_else(|| TypedError::InternalConfig {
            detail: "Guest Relay namespace is unavailable".to_owned(),
            source: None,
        })?;
    let entity = config
        .relay
        .entity
        .ok_or_else(|| TypedError::InternalConfig {
            detail: "Guest Relay entity is unavailable".to_owned(),
            source: None,
        })?;
    let settings =
        RelayTransportSettings::new(namespace, entity).map_err(|_| TypedError::InternalConfig {
            detail: "Guest Relay settings are invalid".to_owned(),
            source: None,
        })?;
    let bundle_bytes = bundle
        .zone_resource_bundle_bytes(identity.zone().as_str())
        .ok_or_else(|| TypedError::InternalConfig {
            detail: "Guest Zone resource bundle is unavailable".to_owned(),
            source: None,
        })?;
    let zone_bundle =
        ResourceBundle::from_json(bundle_bytes).map_err(|_| TypedError::InternalConfig {
            detail: "Guest Zone resource bundle is invalid".to_owned(),
            source: None,
        })?;
    let providers = zone_bundle
        .resources
        .iter()
        .filter(|resource| {
            resource.resource_type().as_str() == "Provider"
                && resource
                    .metadata()
                    .name()
                    .as_str()
                    .starts_with("transport-azure-relay")
        })
        .collect::<Vec<_>>();
    let [provider] = providers.as_slice() else {
        return Err(TypedError::InternalConfig {
            detail: "Guest Relay Provider assignment is unavailable".to_owned(),
            source: None,
        });
    };
    let provider_spec = serde_json::from_slice::<Value>(&provider.spec().to_canonical_bytes())
        .map_err(|_| TypedError::InternalConfig {
            detail: "Guest Relay Provider configuration is invalid".to_owned(),
            source: None,
        })?;
    let provider_config = provider_spec
        .get("config")
        .and_then(Value::as_object)
        .ok_or_else(|| TypedError::InternalConfig {
            detail: "Guest Relay Provider configuration is unavailable".to_owned(),
            source: None,
        })?;
    let execution_ref = provider_config
        .get("executionRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .ok_or_else(|| TypedError::InternalConfig {
            detail: "Guest Relay execution assignment is invalid".to_owned(),
            source: None,
        })?;
    let network_ref = provider_config
        .get("networkRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .ok_or_else(|| TypedError::InternalConfig {
            detail: "Guest Relay network assignment is invalid".to_owned(),
            source: None,
        })?;
    if execution_ref != *identity.guest_ref()
        || execution_ref.resource_type().as_str() != "Guest"
        || network_ref.resource_type().as_str() != "Network"
    {
        return Err(TypedError::InternalConfig {
            detail: "Guest Relay Provider placement is invalid".to_owned(),
            source: None,
        });
    }
    Ok(Some(GatewayGuestZoneLinkOptions {
        credential_path: config.credential_path,
        seal_key_path: config.seal_key_path,
        observation_path,
        execution_ref,
        network_ref,
        settings,
        max_concurrent_sessions: 32,
        connect_timeout_seconds: 30,
    }))
}

#[cfg(test)]
mod gateway_guest_config_tests {
    use super::*;

    /// A typo in the user-written Guest gateway config must be refused at
    /// the deserialization boundary, not silently ignored until the Relay
    /// namespace lookup later fails.

    #[test]
    fn gateway_guest_config_typo_is_refused_at_parse() {
        let error = serde_json::from_slice::<GatewayGuestConfigFile>(
            br#"{"credentialPath":"/run/gateway/cred","sealKeyPath":"/run/gateway/seed","relay":{"namespace":"ns","entity":"ent"},"typoKey":true}"#,
        )
        .expect_err("a typo'd gateway guest config key must be refused");
        assert!(
            error.to_string().contains("unknown field"),
            "the typo must surface as the serde unknown-field error: {error}"
        );
    }

    /// The Relay sub-object refuses unknown keys at the same boundary.

    #[test]
    fn gateway_guest_relay_config_typo_is_refused_at_parse() {
        let error = serde_json::from_slice::<GatewayGuestRelayConfigFile>(
            br#"{"namespace":"ns","entity":"ent","typoKey":true}"#,
        )
        .expect_err("a typo'd relay config key must be refused");
        assert!(
            error.to_string().contains("unknown field"),
            "the typo must surface as the serde unknown-field error: {error}"
        );
    }
}

/// The journal-visible event every accepted Guest ComponentSession publishes.
///
/// The host journal is where the Guest console is forwarded, and `d2bd`'s
/// tracing filter defaults to `info` (`main.rs`), so this is the only level at
/// which the Guest's accept is observable there. The acceptance lane greps the
/// exact message and parses the `generation` field out of it.
pub(crate) const COMPONENT_SESSION_STARTED_EVENT: &str =
    "Guest ComponentSession Resource API server starting";

/// Publish one accepted ComponentSession's live generation.
///
/// Every acceptance - the first one after boot exactly like a replacement
/// after a parent reconnect - announces the generation carried by the accepted
/// session's authenticated route. That route generation is the same value the
/// Guest binds as the live target-control generation
/// (`GuestTargetService::bind_session`) and the same value the parent records
/// in the session descriptor, so one line tells the operator which generation
/// is live on both sides of the boundary.
pub(crate) fn publish_component_session_started(generation: u64) {
    tracing::info!(generation, "{COMPONENT_SESSION_STARTED_EVENT}");
}

/// Start the fixed Guest target agent. Unlike [`serve`], this path never
/// loads `DaemonConfig`, binds a public operator socket, or opens a Host Zone
/// store. Any optional credential input belongs to the Guest-local
/// `GatewayGuestZoneLinkOptions` path.
pub async fn serve_guest(options: GuestServeOptions) -> Result<(), TypedError> {
    if !options.state_dir.is_absolute() || !options.broker_socket_path.is_absolute() {
        return Err(TypedError::InternalConfig {
            detail: "guest mode requires absolute state and broker paths".to_owned(),
            source: None,
        });
    }
    // The production path is sealed to the kernel's boot-id file. A custom
    // path is accepted only by the validation-only characterization route,
    // which never establishes a session or allocates Guest authority.
    let boot_id_path = if options.validate_only {
        options.boot_id_path
    } else {
        PathBuf::from(d2bd_runtime::guest_mode::KERNEL_BOOT_ID_PATH)
    };
    let boot = d2bd_runtime::guest_mode::BootIdentity::read(&boot_id_path).map_err(|_| {
        TypedError::InternalConfig {
            detail: "guest kernel boot identity unavailable".to_owned(),
            source: None,
        }
    })?;
    let guest_ref =
        ResourceRef::parse(&options.guest_ref).map_err(|_| TypedError::InternalConfig {
            detail: "guest identity reference is invalid".to_owned(),
            source: None,
        })?;
    let guest_uid = kernel_guest_uid().await.unwrap_or(options.guest_uid);
    let guest_uid = ResourceUid::parse(guest_uid).map_err(|_| TypedError::InternalConfig {
        detail: "guest identity UID is invalid".to_owned(),
        source: None,
    })?;
    let zone = ZoneId::parse(options.zone).map_err(|_| TypedError::InternalConfig {
        detail: "guest Zone identity is invalid".to_owned(),
        source: None,
    })?;
    let purpose = d2b_contracts_resource::v3::identity::SessionPurpose::parse(options.purpose)
        .map_err(|_| TypedError::InternalConfig {
            detail: "guest session purpose is invalid".to_owned(),
            source: None,
        })?;
    let schema = SchemaFingerprint::parse(options.schema_fingerprint).map_err(|_| {
        TypedError::InternalConfig {
            detail: "guest session schema fingerprint is invalid".to_owned(),
            source: None,
        }
    })?;
    let reconnect_generation =
        ReconnectGeneration::new(options.reconnect_generation).map_err(|_| {
            TypedError::InternalConfig {
                detail: "guest reconnect generation is invalid".to_owned(),
                source: None,
            }
        })?;
    let identity = d2bd_runtime::guest_mode::GuestIdentity::new(
        guest_ref,
        guest_uid,
        zone,
        boot,
        purpose,
        schema,
        reconnect_generation,
        options.provider_generation,
        options.controller_generation,
        options.assignment_epoch,
    )
    .map_err(|error| TypedError::InternalConfig {
        detail: error.to_string(),
        source: error_source(error),
    })?;
    if options.validate_only {
        return Ok(());
    }
    // KTD9: the mkdir is a blocking fs call; the tokio fs driver keeps it
    // off the runtime workers.
    tokio::fs::create_dir_all(&options.state_dir)
        .await
        .map_err(|_| TypedError::InternalConfig {
            detail: "guest state root unavailable".to_owned(),
            source: None,
        })?;
    let runtime = d2bd_runtime::guest_mode::GuestRuntime::new(
        identity.clone(),
        options.broker_socket_path.clone(),
        options.broker_uid,
        d2bd_runtime::target_runtime::AdmissionLimits::guest_default(),
    )
    .await
    .map_err(|error| TypedError::InternalConfig {
        detail: error.to_string(),
        source: error_source(error),
    })?;
    let bundle = BundleResolver::load_on_loader_worker(&options.bundle_path)
        .await
        .inspect_err(|error| {
            tracing::error!(
                error = %error,
                "Guest process bundle validation failed",
            );
        })
        .map_err(|_| TypedError::InternalConfig {
            detail: "guest process bundle unavailable".to_owned(),
            source: None,
        })?;
    let gateway_zone_link = load_gateway_guest_zone_link_options(
        options.gateway_zone_link_config_path.as_deref(),
        &identity,
        &bundle,
    )
    .await?
    .map(|config| {
        let observation_path = config.observation_path;
        let runtime = d2b_provider_transport_azure_relay::GatewayGuestZoneLinkRuntime::from_sealed(
            config.credential_path,
            config.seal_key_path,
            &d2b_provider_transport_azure_relay::CredentialFilePolicy::default(),
            d2b_provider_transport_azure_relay::GatewayGuestZoneLinkTransportConfig {
                execution_ref: config.execution_ref,
                network_ref: config.network_ref,
                settings: config.settings,
                max_concurrent_sessions: config.max_concurrent_sessions,
                connect_timeout_seconds: config.connect_timeout_seconds,
            },
        )
        .map_err(|error| TypedError::InternalConfig {
            detail: error.code().to_owned(),
            source: None,
        })?;
        Ok::<_, TypedError>((runtime, observation_path))
    })
    .transpose()?;
    if gateway_zone_link.is_some() {
        tracing::info!(
            zone = %identity.zone(),
            guest_ref = %identity.guest_ref().name().as_str(),
            "Guest-local ZoneLink transport Provider composed",
        );
    }
    let local_private_path =
        options
            .local_private_key_path
            .ok_or_else(|| TypedError::InternalConfig {
                detail: "guest ComponentSession private key is unavailable".to_owned(),
                source: None,
            })?;
    let parent_public_path =
        options
            .parent_public_key_path
            .ok_or_else(|| TypedError::InternalConfig {
                detail: "parent Zone ComponentSession key is unavailable".to_owned(),
                source: None,
            })?;
    let parent_public = read_public_key32(&parent_public_path).await?;
    let mut listener = runtime
        .bind_listener()
        .map_err(|error| TypedError::InternalConfig {
            detail: error.to_string(),
            source: error_source(error),
        })?;
    tracing::info!(
        port = d2bd_runtime::guest_mode::GUEST_COMPONENT_SESSION_PORT,
        "Guest ComponentSession listener bound",
    );
    if let Some((gateway_zone_link, Some(observation_path))) = gateway_zone_link.as_ref() {
        gateway_zone_link
            .write_open_observation(observation_path)
            .map_err(|error| TypedError::InternalConfig {
                detail: error.code().to_owned(),
                source: None,
            })?;
    }
    // Guest target-control (U13 guest half): one target runtime per Guest,
    // driven by the requests the parent Zone sends over this session. The
    // service survives reconnects so target-local realizations can be
    // re-adopted (F5); the live generation is bound at every accept, and the
    // types it serves are exactly the ones with registered target-local
    // effect code (none yet - see `guest_target_service`).
    let guest_target =
        d2b_resource_runtime::target::TargetRef::guest(identity.guest_ref().name().as_str())
            .map_err(|error| TypedError::InternalConfig {
                detail: error.to_string(),
                source: error_source(error),
            })?;
    let target_service = std::sync::Arc::new(
        d2b_provider_guest::GuestTargetService::new(
            std::sync::Arc::new(d2b_resource_runtime::guest_target::GuestTargetRuntime::new(
                guest_target,
            )),
            identity.zone().clone(),
            d2b_provider_guest::production_guest_target_effects(),
        ),
    );
    tracing::info!(
        zone = %identity.zone(),
        guest_ref = %identity.guest_ref().name().as_str(),
        "Guest target-control service composed",
    );
    let mut sigterm = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
        .map_err(|_| TypedError::InternalIo {
            context: "install Guest SIGTERM handler".to_owned(),
            detail: "signal handler unavailable".to_owned(),
            source: None,
        })?;
    let mut sigint = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::interrupt())
        .map_err(|_| TypedError::InternalIo {
            context: "install Guest SIGINT handler".to_owned(),
            detail: "signal handler unavailable".to_owned(),
            source: None,
        })?;
    let mut active: Option<(
        tokio::task::JoinHandle<Result<(), d2b_session::SessionServerError>>,
        d2bd_runtime::guest_mode::GuestSessionLease,
    )> = None;
    loop {
        let local_private = read_secret32(&local_private_path).await?;
        if let Some((mut serving, lease)) = active.take() {
            tokio::select! {
                _ = sigterm.recv() => {
                    serving.abort();
                    let _ = serving.await;
                    drop(lease);
                    break;
                },
                _ = sigint.recv() => {
                    serving.abort();
                    let _ = serving.await;
                    drop(lease);
                    break;
                },
                accepted = runtime.accept_from_parent(&mut listener, local_private, parent_public) => {
                    let (session, new_lease) = match accepted {
                        Ok(session) => session,
                        Err(error) => {
                            tracing::warn!(error = %error, "Guest ComponentSession handshake refused");
                            active = Some((serving, lease));
                            continue;
                        }
                    };
                    serving.abort();
                    let _ = serving.await;
                    drop(lease);
                    let route = session.route_binding();
                    let resource_session = match runtime.resource_runtime().bind_session(&route) {
                        Ok(session) => session,
                        Err(error) => {
                            tracing::warn!(error = %error, "Guest Resource API session binding refused");
                            drop(new_lease);
                            continue;
                        }
                    };
                    if let Err(error) =
                        target_service.bind_session(route.reconnect_generation().get())
                    {
                        tracing::warn!(
                            error = %error,
                            generation = route.reconnect_generation().get(),
                            "Guest target-control session binding refused",
                        );
                    }
                    let config_services = match guest_config_services(&identity, &route, &options.guest_config_path) {
                        Ok(services) => services,
                        Err(error) => {
                            tracing::warn!(error = %error, "Guest config service binding refused");
                            drop(new_lease);
                            continue;
                        }
                    };
                    let mut services = resource_session.ttrpc_services();
                    services.extend(config_services);
                    services.extend(
                        d2b_provider_guest::target_control_services(Arc::clone(
                            &target_service,
                        )),
                    );
                    let ttrpc = session.into_ttrpc_handle();
                    let generation = route.reconnect_generation().get();
                    publish_component_session_started(generation);
                    active = Some((
                        tokio::spawn(async move {
                            let result = ttrpc.serve_ttrpc_services(services).await;
                            tracing::warn!(
                                generation,
                                result = ?result,
                                "Guest ComponentSession Resource API server stopped",
                            );
                            result
                        }),
                        new_lease,
                    ));
                },
                result = &mut serving => {
                    if let Ok(Err(error)) = result {
                        tracing::debug!(error = %error, "Guest ComponentSession resource server stopped");
                    }
                    drop(lease);
                },
            }
        } else {
            let accepted = tokio::select! {
                _ = sigterm.recv() => break,
                _ = sigint.recv() => break,
                result = runtime.accept_from_parent(&mut listener, local_private, parent_public) => result,
            };
            let (session, lease) = match accepted {
                Ok(session) => session,
                Err(error) => {
                    if options.once {
                        return Err(TypedError::InternalConfig {
                            detail: error.to_string(),
                            source: error_source(error),
                        });
                    }
                    tracing::warn!(error = %error, "Guest ComponentSession handshake refused");
                    continue;
                }
            };
            if options.once {
                drop(lease);
                return Ok(());
            }
            let route = session.route_binding();
            let resource_session = match runtime.resource_runtime().bind_session(&route) {
                Ok(session) => session,
                Err(error) => {
                    tracing::warn!(error = %error, "Guest Resource API session binding refused");
                    drop(lease);
                    continue;
                }
            };
            if let Err(error) = target_service.bind_session(route.reconnect_generation().get()) {
                tracing::warn!(
                    error = %error,
                    generation = route.reconnect_generation().get(),
                    "Guest target-control session binding refused",
                );
            }
            let config_services =
                match guest_config_services(&identity, &route, &options.guest_config_path) {
                    Ok(services) => services,
                    Err(error) => {
                        tracing::warn!(error = %error, "Guest config service binding refused");
                        drop(lease);
                        continue;
                    }
                };
            let mut services = resource_session.ttrpc_services();
            services.extend(config_services);
            services.extend(d2b_provider_guest::target_control_services(
                Arc::clone(&target_service),
            ));
            let ttrpc = session.into_ttrpc_handle();
            publish_component_session_started(route.reconnect_generation().get());
            active = Some((
                tokio::spawn(async move { ttrpc.serve_ttrpc_services(services).await }),
                lease,
            ));
        }

        fn guest_config_services(
            identity: &d2bd_runtime::guest_mode::GuestIdentity,
            route: &d2b_session::AuthenticatedSessionRouteBinding,
            path: &Path,
        ) -> Result<std::collections::HashMap<String, ttrpc::r#async::Service>, String> {
            identity
                .validate_route(route)
                .map_err(|error| error.to_string())?;
            let boot_digest = identity
                .boot_identity()
                .digest()
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect::<String>();
            let backend = d2b_provider_config_nixos::GuestConfigReader::new(
                identity.guest_ref().clone(),
                format!("sha256:{boot_digest}"),
                route.reconnect_generation().get(),
                path,
            )
            .map_err(|error| error.code().to_owned())?;
            Ok(d2b_provider_config_nixos::create_ttrpc_services(
                std::sync::Arc::new(backend),
            ))
        }
    }
    Ok(())
}

async fn read_secret32(path: &Path) -> Result<d2b_session::Secret32, TypedError> {
    let bytes = tokio::fs::read(path).await.map_err(|_| TypedError::InternalConfig {
        detail: "guest ComponentSession private key unavailable".to_owned(),
        source: None,
    })?;
    let bytes: [u8; 32] = bytes.try_into().map_err(|_| TypedError::InternalConfig {
        detail: "guest ComponentSession private key has invalid length".to_owned(),
        source: None,
    })?;
    d2b_session::Secret32::new(bytes).map_err(|_| TypedError::InternalConfig {
        detail: "guest ComponentSession private key is invalid".to_owned(),
        source: None,
    })
}

async fn read_public_key32(path: &Path) -> Result<[u8; 32], TypedError> {
    let bytes = tokio::fs::read(path).await.map_err(|_| TypedError::InternalConfig {
        detail: "parent Zone ComponentSession key unavailable".to_owned(),
        source: None,
    })?;
    let bytes: [u8; 32] = bytes.try_into().map_err(|_| TypedError::InternalConfig {
        detail: "parent Zone ComponentSession key has invalid length".to_owned(),
        source: None,
    })?;
    if bytes == [0; 32] {
        return Err(TypedError::InternalConfig {
            detail: "parent Zone ComponentSession key is invalid".to_owned(),
            source: None,
        });
    }
    Ok(bytes)
}

/// Drain the published v3 planes' providers.
///
/// Each plane drains its providers through the base in the reverse of the
/// order it started them. The planes are visited in zone order so the
/// sequence is deterministic; a refusal is logged with the provider and the
/// row the base named, and the remaining planes still drain.
async fn drain_v3_providers(state: &ServerState) {
    let mut planes: Vec<(String, std::sync::Arc<crate::resource_plane_v3::ResourcePlaneV3>)> = state
        .v3_planes
        .lock()
        .await
        .iter()
        .map(|(zone, plane)| (zone.clone(), std::sync::Arc::clone(plane)))
        .collect();
    planes.sort_by(|left, right| left.0.cmp(&right.0));
    for (zone, plane) in planes {
        match plane.drain_providers().await {
            Ok(()) => tracing::debug!(
                zone = %zone,
                providers = ?plane.providers().drain_order(),
                "v3 providers drained in the reverse of their startup order"
            ),
            Err(error) => tracing::warn!(
                zone = %zone,
                provider = %error.provider_ref(),
                error = %error,
                "v3 provider drain refused"
            ),
        }
    }
}

async fn finalize_daemon_interactions(state: &ServerState) -> Result<(), TypedError> {
    if let Some(listeners) = state.interaction_listeners.lock().await.take()
    {
        listeners.stop().await;
    }
    let interaction_error = match interaction_composition::finalize_interaction_runtimes(
        &state.interaction_runtime,
        d2b_provider_display_wayland::GraceState::Expired,
    )
    .await
    {
        Some(error) => {
            tracing::error!(?error, "interaction Provider finalization failed");
            Some(TypedError::InternalIo {
                context: "interaction Provider finalization".to_owned(),
                detail: error.to_string(),
                source: error_source(error),
            })
        }
        None => None,
    };
    let runtime = state.interaction_runtime.lock().await.take();
    // The interaction composition retains the Resource API client used by
    // durable display children. Drop it before the resource plane's
    // Arc::try_unwrap shutdown gate runs.
    drop(runtime);
    let resource_result = shutdown_resource_plane(state).await;
    drain_v3_providers(state).await;
    if let Some(error) = interaction_error {
        if let Err(resource_error) = resource_result {
            tracing::error!(
                ?resource_error,
                "resource-plane shutdown also failed after interaction finalization failure"
            );
        }
        return Err(error);
    }
    resource_result.map_err(|error| TypedError::InternalIo {
        context: "authoritative resource-plane shutdown audit".to_owned(),
        detail: error.to_string(),
        source: error_source(error),
    })
}

/// Acquire the daemon's state lock and hold it for the requested duration,
/// then release it. Operator tooling uses this to serialize exclusive
/// state access without starting the daemon.
///
/// # Errors
///
/// Returns [`TypedError`] for config-load, state-lock-parent validation, and
/// lock-acquisition failures.
pub async fn lock_only(options: LockOnlyOptions) -> Result<(), TypedError> {
    let mut config = load_config(&options.config_path)?;
    if let Some(path) = options.state_lock_path.clone() {
        config.state_lock_path = path;
    }
    let runtime_identity =
        resolve_runtime_identity(&config, options.allow_unprivileged_runtime_dir)?;
    validate_lock_parent(&config.state_lock_path, &runtime_identity)?;
    let _lock_file = acquire_state_lock(&config.state_lock_path, &runtime_identity)?;
    tokio::time::sleep(tokio::time::Duration::from_secs(options.hold_seconds)).await;
    Ok(())
}

struct BrokerPidfdOpener<'a> {
    state: &'a ServerState,
}

impl d2bd_runtime::supervisor::state::PidfdOpener for BrokerPidfdOpener<'_> {
    fn open_pidfd(
        &self,
        vm: &str,
        _role_id: &str,
        pid: i32,
        expected_start_time_ticks: u64,
    ) -> Result<OwnedFd, String> {
        // The U10 kernel leg: the open-pidfd kernel performs the same
        // `pidfd_open` plus start-time verification the retired typed arm's
        // live handler ran, and returns the pidfd over the fd leg.
        let zone = match kernel_zone_for_vm(self.state, vm) {
            Ok(zone) => zone,
            Err(error) => return Err(format!("broker-dispatch:{error}")),
        };
        match envelope_invoke_kernel(
            &broker_socket_path(self.state),
            KERNEL_IO_TIMEOUT,
            BrokerCallerRole::AdminUid {
                uid: self.state.daemon_uid,
            },
            KernelInvocation {
                operation: "open-pidfd",
                zone: &zone,
                payload: serde_json::json!({
                    "pid": pid,
                    "expectedStartTimeTicks": expected_start_time_ticks,
                }),
                fds: &[],
                chain_root_invocation_id: None,
                chain_identities: None,
            },
        ) {
            Ok(reply) => {
                let verified = reply
                    .response
                    .result
                    .as_ref()
                    .and_then(|result| result.get("verifiedStartTimeTicks"))
                    .and_then(serde_json::Value::as_i64)
                    .map(|value| value as u64);
                let mut fds = reply.fds;
                let pidfd = fds.remove(0);
                if verified != Some(expected_start_time_ticks) {
                    Err("broker-response-mismatch".to_owned())
                } else {
                    Ok(pidfd)
                }
            }
            Err(error) => Err(format!("broker-dispatch:{error}")),
        }
    }
}

async fn adopt_orphaned_runners_on_startup(state: &ServerState) {
    if let Some(providers) = state.provider_runtime.process_providers() {
        let store =
            d2bd_runtime::supervisor::state::FilesystemSnapshotStore::new(&state.daemon_state_dir);
        let snapshots = match d2bd_runtime::supervisor::state::SnapshotStore::list(&store) {
            Ok(snapshots) => snapshots,
            Err(error) => {
                tracing::warn!(
                    error = %error,
                    "Provider startup adoption refused because runner snapshots are unavailable"
                );
                return;
            }
        };
        let result = async {
            for vm in providers.vm_ids() {
                let expected = current_runner_lifecycle_identity(state, &vm).await;
                let managed_roles = providers
                    .managed_role_ids(&vm)
                    .into_iter()
                    .collect::<BTreeSet<_>>();
                for snapshot in snapshots.iter().filter(|snapshot| snapshot.vm == vm) {
                    if !managed_roles.contains(&snapshot.role_id)
                        || !runner_snapshot_is_eligible(snapshot, expected.as_ref())
                    {
                        tracing::warn!(
                            vm = %snapshot.vm,
                            role = %snapshot.role_id,
                            "Provider startup adoption quarantined runner snapshot"
                        );
                    }
                }
                let eligible_roles = snapshots
                    .iter()
                    .filter(|snapshot| snapshot.vm == vm)
                    .filter(|snapshot| managed_roles.contains(&snapshot.role_id))
                    .filter(|snapshot| runner_snapshot_is_eligible(snapshot, expected.as_ref()))
                    .map(|snapshot| snapshot.role_id.clone())
                    .collect::<BTreeSet<_>>();
                providers.adopt_vm(&vm, &eligible_roles).await?;
                let _guard = state.pidfd_table.mutation_guard();
                for role in eligible_roles {
                    let _ = state.pidfd_table.deregister(&vm, &role);
                }
                state
                    .pidfd_table
                    .snapshot()
                    .map_err(|error| format!("provider-legacy-authority-cleanup:{error}"))?;
            }
            Ok::<(), String>(())
        }
        .await;
        if let Err(error) = result {
            tracing::warn!(
                error = %error,
                "Provider startup adoption failed; ambiguous processes remain quarantined"
            );
        }
        return;
    }
    let store =
        d2bd_runtime::supervisor::state::FilesystemSnapshotStore::new(&state.daemon_state_dir);
    let proc_reader = d2bd_runtime::supervisor::state::SystemProcReader;
    let opener = BrokerPidfdOpener { state };
    if let Err(error) = adopt_orphaned_runners_on_startup_with(state, &store, &proc_reader, &opener).await
    {
        tracing::warn!(error = ?error, "startup orphan adoption failed");
    }
}

async fn adopt_orphaned_runners_on_startup_with(
    state: &ServerState,
    store: &dyn d2bd_runtime::supervisor::state::SnapshotStore,
    proc_reader: &dyn d2bd_runtime::supervisor::state::ProcReader,
    opener: &dyn d2bd_runtime::supervisor::state::PidfdOpener,
) -> Result<(), TypedError> {
    let snapshots = d2bd_runtime::supervisor::state::SnapshotStore::list(store).map_err(|err| {
        TypedError::InternalIo {
            context: "enumerate daemon runner snapshots".to_owned(),
            detail: err.to_string(),
            source: error_source(err),
        }
    })?;
    if snapshots.is_empty() {
        return Ok(());
    }

    let mut eligible_snapshots = Vec::with_capacity(snapshots.len());
    for snapshot in &snapshots {
        if !snapshot.has_complete_lifecycle_identity() {
            tracing::warn!(
                vm = %snapshot.vm,
                role = %snapshot.role_id,
                "startup adoption quarantined runner snapshot without lifecycle identity"
            );
            continue;
        }
        if !runner_snapshot_is_eligible(
            snapshot,
            current_runner_lifecycle_identity(state, &snapshot.vm).await.as_ref(),
        ) {
            tracing::warn!(
                vm = %snapshot.vm,
                role = %snapshot.role_id,
                "startup adoption quarantined runner snapshot with stale lifecycle identity"
            );
            continue;
        }
        eligible_snapshots.push(snapshot.clone());
    }

    let snapshot_index: BTreeMap<
        (String, String),
        &d2bd_runtime::supervisor::state::RunnerSnapshotRecord,
    > = snapshots
        .iter()
        .map(|snapshot| ((snapshot.vm.clone(), snapshot.role_id.clone()), snapshot))
        .collect();

    for adopt in d2bd_runtime::supervisor::state::reconcile_and_adopt(
        &eligible_snapshots,
        proc_reader,
        opener,
    ) {
        let key = (adopt.vm.clone(), adopt.role_id.clone());
        let Some(snapshot) = snapshot_index.get(&key) else {
            continue;
        };
        match adopt.outcome {
            d2bd_runtime::supervisor::state::AdoptOutcome::Adopted(pidfd) => {
                if state.pidfd_table.contains(&adopt.vm, &adopt.role_id) {
                    tracing::info!(
                        vm = %adopt.vm,
                        role = %adopt.role_id,
                        "startup adoption skipped because pidfd table already restored the runner"
                    );
                    continue;
                }
                match state.pidfd_table.register(
                    adopt.vm.clone(),
                    adopt.role_id.clone(),
                    PidfdEntry {
                        pidfd,
                        pid: snapshot.pid,
                        start_time_ticks: snapshot.start_time_ticks,
                    },
                ) {
                    Ok(()) => {
                        tracing::info!(
                            vm = %adopt.vm,
                            role = %adopt.role_id,
                            pid = snapshot.pid,
                            start_time_ticks = snapshot.start_time_ticks,
                            "adopted runner snapshot into pidfd table"
                        );
                    }
                    Err(PidfdTableError::DuplicateRegistration { .. }) => {
                        tracing::info!(
                            vm = %adopt.vm,
                            role = %adopt.role_id,
                            "startup adoption observed a duplicate pidfd-table registration"
                        );
                    }
                    Err(error) => {
                        return Err(TypedError::InternalIo {
                            context: "register adopted pidfd".to_owned(),
                            detail: error.to_string(),
                            source: error_source(error),
                        });
                    }
                }
            }
            d2bd_runtime::supervisor::state::AdoptOutcome::Quarantine {
                observed_start_time_ticks,
            } => {
                tracing::warn!(
                    vm = %adopt.vm,
                    role = %adopt.role_id,
                    pid = snapshot.pid,
                    expected_start_time_ticks = snapshot.start_time_ticks,
                    observed_start_time_ticks,
                    "startup adoption quarantined runner snapshot"
                );
            }
            d2bd_runtime::supervisor::state::AdoptOutcome::QuarantineIdentity => {
                tracing::warn!(
                    vm = %adopt.vm,
                    role = %adopt.role_id,
                    "startup adoption quarantined runner snapshot without complete lifecycle identity"
                );
            }
            d2bd_runtime::supervisor::state::AdoptOutcome::Missing => {
                d2bd_runtime::supervisor::state::SnapshotStore::remove(
                    store,
                    &adopt.vm,
                    &adopt.role_id,
                )
                .map_err(|err| TypedError::InternalIo {
                    context: "remove missing runner snapshot".to_owned(),
                    detail: err.to_string(),
                    source: error_source(err),
                })?;
                tracing::info!(
                    vm = %adopt.vm,
                    role = %adopt.role_id,
                    pid = snapshot.pid,
                    "startup adoption removed stale missing runner snapshot"
                );
            }
            d2bd_runtime::supervisor::state::AdoptOutcome::AdoptRaced { detail } => {
                if transient_adoption_error(&detail) {
                    tracing::warn!(
                        vm = %adopt.vm,
                        role = %adopt.role_id,
                        pid = snapshot.pid,
                        detail = %detail,
                        "startup adoption could not reopen pidfd; leaving snapshot on disk"
                    );
                    continue;
                }
                d2bd_runtime::supervisor::state::SnapshotStore::remove(
                    store,
                    &adopt.vm,
                    &adopt.role_id,
                )
                .map_err(|err| TypedError::InternalIo {
                    context: "remove raced runner snapshot".to_owned(),
                    detail: err.to_string(),
                    source: error_source(err),
                })?;
                tracing::warn!(
                    vm = %adopt.vm,
                    role = %adopt.role_id,
                    pid = snapshot.pid,
                    detail = %detail,
                    "startup adoption dropped runner snapshot after pidfd reopen race"
                );
            }
            d2bd_runtime::supervisor::state::AdoptOutcome::UnparseableProcStat { detail } => {
                tracing::warn!(
                    vm = %adopt.vm,
                    role = %adopt.role_id,
                    pid = snapshot.pid,
                    detail = %detail,
                    "startup adoption quarantined runner snapshot with unparseable proc stat"
                );
            }
        }
    }

    state
        .pidfd_table
        .snapshot()
        .map_err(|err| TypedError::InternalIo {
            context: "persist adopted pidfd table".to_owned(),
            detail: err.to_string(),
            source: error_source(err),
        })?;
    Ok(())
}

async fn current_runner_lifecycle_identity(
    state: &ServerState,
    vm: &str,
) -> Option<(
    ResourceUid,
    ResourceUid,
    ResourceGeneration,
    ResourceGeneration,
    u64,
)> {
    let zone = d2bd_runtime::zone_authority::authoritative_zone_for_vm(
        &state.zone_coordinator,
        vm,
    )
    .await
        .ok()?;
    let plane = state.resource_plane.try_lock().ok()?.clone()?;
    let runtime = plane.zone(&zone).ok()?;
    let target = ResourceRef::parse(&format!("Guest/{vm}")).ok()?;
    let (zone_uid, guest_uid, guest_generation, provider_generation) =
        runtime.guest_lifecycle_identity(&target).await.ok()?;
    let policy_revision = runtime.committed_policy_snapshot().policy_revision;
    Some((
        zone_uid,
        guest_uid,
        guest_generation,
        provider_generation,
        policy_revision,
    ))
}

fn runner_snapshot_is_eligible(
    snapshot: &d2bd_runtime::supervisor::state::RunnerSnapshotRecord,
    expected: Option<&(
        ResourceUid,
        ResourceUid,
        ResourceGeneration,
        ResourceGeneration,
        u64,
    )>,
) -> bool {
    snapshot.has_complete_lifecycle_identity()
        && expected.is_some_and(|expected| {
            snapshot.matches_lifecycle_identity(
                &expected.0,
                &expected.1,
                expected.2,
                expected.3,
                expected.4,
            )
        })
}

fn transient_adoption_error(detail: &str) -> bool {
    detail.starts_with("broker-")
}

// =====================================================================
// d2bd autostart contract glue.
// The plan + executor live in `autostart`; this section wires the
// production starter (which dispatches into `dispatch_broker_vm_start`)
// and the startup invocation. See docs/reference/daemon-autostart.md.
// =====================================================================

/// Production [`d2bd_runtime::autostart::VmStarter`] backed by the live broker
/// dispatch path. Wraps `ServerState` in an `Arc` so the autostart
/// `JoinSet` tasks can each hold a reference.
struct BrokerVmStarter {
    state: Arc<ServerState>,
}

impl d2bd_runtime::autostart::VmStarter for BrokerVmStarter {
    fn is_running(&self, vm: &str) -> bool {
        // Idempotency check mirrors the duplicate-pidfd guard in
        // `dispatch_broker_vm_start`: if the ch-runner role is
        // already registered, the VM is supervised.
        if let Some(providers) = self.state.provider_runtime.process_providers() {
            return providers.has_active_role(vm, VM_RUNNER_ROLE_ID) || providers.has_active_vm(vm);
        }
        self.state.pidfd_table.contains(vm, VM_RUNNER_ROLE_ID)
    }

    fn start(&self, vm: &str) -> Result<(), String> {
        let request = public_wire::VmLifecycleRequest {
            vm: vm.to_owned(),
            flags: public_wire::MutationFlags {
                mode: public_wire::MutationMode::Apply,
                json: true,
            },
            force: false,
            // Opt-IN to relaxed semantics so api-ready timeout (common
            // during cold boot of net VMs) does not
            // cascade-degrade every workload VM in the env. The
            // strict-default contract is preserved for explicit
            // `d2b vm start --apply` invocations.
            no_wait_api: true,
        };
        match dispatch_broker_vm_start_as(
            &self.state,
            request,
            BrokerCallerRole::RootUid {
                uid: self.state.daemon_uid,
            },
        ) {
            Ok(value) => {
                // dispatch_broker_vm_start returns a JSON envelope
                // even on logical failure (so the public verb can
                // surface it). For autostart we accept the
                // "applied" outcome regardless of api-ready state
                // (--no-wait-api means api-ready: pending is expected
                // during cold boot
                // and is NOT a failure).
                let outcome_ok = value
                    .get("outcome")
                    .and_then(|v| v.as_str())
                    .map(|s| s == "applied")
                    .unwrap_or(false);
                if outcome_ok {
                    Ok(())
                } else {
                    Err(value.to_string())
                }
            }
            Err(error) => Err(error.message()),
        }
    }
}

/// Drive the autostart plan against the live daemon on startup.
/// Logged outcomes are best-effort: any failure short-circuits to
/// a warning so the daemon's accept loop still comes up.
async fn run_startup_autostart(state: &ServerState, kernel_module_degraded: &BTreeSet<String>) {
    let resolver = match load_bundle_resolver_on_worker(state).await {
        Ok(r) => r,
        Err(error) => {
            tracing::warn!(
                error = %error.message(),
                "autostart skipped: bundle resolver unavailable",
            );
            return;
        }
    };
    let plan = d2bd_runtime::autostart::build_autostart_plan(&resolver);
    if plan.vms.is_empty() {
        tracing::info!(
            net_vm_count = plan.net_vms().count(),
            workload_count = plan.workload_vms().count(),
            "autostart: nothing to do (empty plan)",
        );
        return;
    }
    tracing::info!(
        net_vm_count = plan.net_vms().count(),
        workload_count = plan.workload_vms().count(),
        parallelism = state.config.autostart_parallelism,
        "autostart: dispatching plan",
    );
    let starter = Arc::new(BrokerVmStarter {
        state: Arc::new(state.clone()),
    });
    let config = d2bd_runtime::autostart::AutostartConfig {
        parallelism: state.config.autostart_parallelism,
    };
    let report = d2bd_runtime::autostart::execute_autostart_with_pre_degraded(
        &plan,
        starter,
        config,
        kernel_module_degraded,
    )
    .await;
    persist_autostart_report(&state.daemon_state_dir, &report);
    tracing::info!(
        started = report.started(),
        already_running = report.already_running(),
        failed = report.failed(),
        degraded = report.degraded(),
        "autostart: complete",
    );
    for outcome in &report.outcomes {
        match &outcome.outcome {
            d2bd_runtime::autostart::Outcome::Started => {
                tracing::info!(vm = %outcome.vm, "autostart: started");
            }
            d2bd_runtime::autostart::Outcome::AlreadyRunning => {
                tracing::info!(vm = %outcome.vm, "autostart: already-running (skipped)");
            }
            d2bd_runtime::autostart::Outcome::NotAutostart => {
                tracing::debug!(vm = %outcome.vm, "autostart: vm not autostart-eligible");
            }
            d2bd_runtime::autostart::Outcome::Failed { reason } => {
                tracing::warn!(vm = %outcome.vm, reason = %reason, "autostart: failed");
            }
            d2bd_runtime::autostart::Outcome::Degraded { reason } => {
                tracing::warn!(vm = %outcome.vm, reason = %reason, "autostart: degraded");
            }
        }
    }

    // USBIP backend/proxy runners are attach-owned, not startup-owned:
    // `d2b usb attach --apply` first validates/binds/locks the
    // busid, then opens the firewall and starts the per-env runners.
    // Starting the listener here would expose TCP/3240 before the
    // per-busid ownership decision.
    let _ = resolver;
}

/// Thin wrapper used by the `options.once` test path and by direct
/// unit-test callers: authorizes the peer (SO_PEERCRED), then runs the
/// authorized connection body. The production accept loop authorizes the
/// peer itself (before admission) and calls
/// [`handle_connection_authorized`] directly.
fn handle_connection(
    stream: Socket,
    state: &ServerState,
    permit: Option<d2bd_runtime::concurrency::ConnPermit>,
) -> Result<(), TypedError> {
    let peer = match authorize_peer(&stream, &admission_config(state)) {
        Ok(peer) => peer,
        Err(error) => {
            let _ = write_json_frame(&stream, &d2bd_runtime::wire::hello_rejected(&error));
            // Authz ran before the hello read; drain the unread hello so the
            // close is graceful and the peer receives the rejection frame.
            drain_rejected_peer_input(&stream);
            return Err(error);
        }
    };
    handle_connection_authorized(stream, state, peer, permit)
}

/// Connection body for an already-authorized peer. Reads the hello frame
/// (deadlined), negotiates the wire version, then serves requests on a
/// deadlined per-frame read loop. An attached `Exec::Start` or typed-shell
/// request takes over the connection on a spawned owner thread, moving the
/// admission `permit` with it so the in-flight slot is held until the owner
/// session terminates.
fn handle_connection_authorized(
    stream: Socket,
    state: &ServerState,
    peer: PeerIdentity,
    permit: Option<d2bd_runtime::concurrency::ConnPermit>,
) -> Result<(), TypedError> {
    // Bound the wait for the initial hello so a connected-but-silent peer
    // cannot occupy a handler slot indefinitely.
    set_frame_read_deadline(&stream, Some(HELLO_READ_DEADLINE));
    let hello_bytes = match read_frame(&stream) {
        Ok(bytes) => bytes,
        Err(error) => {
            let _ = write_json_frame(&stream, &d2bd_runtime::wire::hello_rejected(&error));
            return Err(error);
        }
    };
    let hello = d2bd_runtime::wire::parse_hello(&hello_bytes).inspect_err(|error| {
        let _ = write_json_frame(&stream, &d2bd_runtime::wire::hello_rejected(error));
    })?;
    let selected_version = match d2bd_runtime::wire::negotiate_version(
        hello.client_version.as_str(),
        &state.config.accepted_client_version_range,
        &state.config.server_version,
    ) {
        Ok(version) => version,
        Err(error) => {
            let _ = write_json_frame(&stream, &d2bd_runtime::wire::hello_rejected(&error));
            return Err(error);
        }
    };
    let advertised_capabilities = [
        KnownFeatureFlag::TypedErrors.wire_value(),
        KnownFeatureFlag::StatusCheckBridges.wire_value(),
        KnownFeatureFlag::ExportBrokerAudit.wire_value(),
        KnownFeatureFlag::ConfiguredLaunchV1.wire_value(),
        KnownFeatureFlag::UnsafeLocalProviderV1.wire_value(),
    ];
    let capabilities = advertised_capabilities
        .into_iter()
        .filter(|capability| {
            hello
                .supported_features
                .iter()
                .any(|requested| requested.known() == capability.known())
        })
        .collect::<Vec<_>>();
    let hello_ok = d2bd_runtime::wire::hello_ok(
        &state.config.server_version,
        &selected_version,
        &capabilities,
    )?;
    write_json_frame(&stream, &hello_ok)?;

    loop {
        // Bound each request read so a half-open / slow-loris peer frees
        // its handler slot instead of pinning it forever.
        set_frame_read_deadline(&stream, Some(REQUEST_READ_DEADLINE));
        let frame = match read_frame(&stream) {
            Ok(bytes) => bytes,
            Err(TypedError::InternalIo { .. }) => return Ok(()),
            Err(error) => {
                let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
                return Err(error);
            }
        };
        let request = match d2bd_runtime::wire::parse_request(&frame) {
            Ok(request) => request,
            Err(error) => {
                let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
                continue;
            }
        };
        if matches!(request, d2bd_runtime::wire::Request::Workload(_))
            && (!capabilities
                .iter()
                .any(|feature| feature.known() == Some(KnownFeatureFlag::ConfiguredLaunchV1))
                || !capabilities.iter().any(|feature| {
                    feature.known() == Some(KnownFeatureFlag::UnsafeLocalProviderV1)
                }))
        {
            let error = TypedError::WireUnsupportedRequest {
                request_type: "workload".to_owned(),
            };
            let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
            continue;
        }
        let gateway_resource_route = if matches!(peer.role, PeerRole::Admin) {
            match &request {
                d2bd_runtime::wire::Request::Resource(resource) => {
                    if let Ok(runtime) = resolve_resource_runtime(state, &resource.value()) {
                        match classify_gateway_zone_request(state, &runtime, &resource.value()) {
                            Ok(route) => Some(route),
                            Err(error) => {
                                let _ =
                                    write_json_frame(&stream, &resource_runtime_error_frame(error));
                                continue;
                            }
                        }
                    } else {
                        None
                    }
                }
                _ => None,
            }
        } else {
            None
        };
        if let d2bd_runtime::wire::Request::Resource(resource) = &request
            && typed_shell_request(&resource.value())
            && gateway_resource_route != Some(GatewayZoneRequestRoute::Forward)
        {
            if !matches!(peer.role, PeerRole::Admin) {
                let error = TypedError::AuthzNotAdmin {
                    verb: "shell".to_owned(),
                };
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                continue;
            }
            if let Err(error) = resolve_typed_shell_runtime(state, &resource.value()) {
                let _ = write_json_frame(&stream, &resource_runtime_error_frame(error));
                continue;
            }
            set_frame_read_deadline(&stream, None);
            let owner_state = state.clone();
            let owner_peer = peer.clone();
            let owner_request = resource.value();
            let owner_permit = permit;
            match spawn_typed_shell_owner(
                stream,
                owner_state,
                owner_peer,
                owner_request,
                owner_permit,
            ) {
                Ok(_) => return Ok(()),
                Err(err) => {
                    return Err(TypedError::InternalIo {
                        context: "spawn typed shell owner handler".to_owned(),
                        detail: err.to_string(),
                        source: error_source(err),
                    });
                }
            }
        }
        if let d2bd_runtime::wire::Request::Resource(resource) = &request
            && process_resource_owner_request(&resource.value())
            && gateway_resource_route != Some(GatewayZoneRequestRoute::Forward)
        {
            if !matches!(peer.role, PeerRole::Admin) {
                let error = TypedError::AuthzNotAdmin {
                    verb: "exec".to_owned(),
                };
                let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
                continue;
            }
            set_frame_read_deadline(&stream, None);
            let owner_state = state.clone();
            let owner_peer = peer.clone();
            let owner_request = resource.value();
            let owner_permit = permit;
            match std::thread::Builder::new()
                .name("d2b-process-owner".to_owned())
                .spawn(move || {
                    run_process_resource_owner(
                        stream,
                        owner_state,
                        owner_peer,
                        owner_request,
                        owner_permit,
                    );
                }) {
                Ok(_) => return Ok(()),
                Err(err) => {
                    return Err(TypedError::InternalIo {
                        context: "spawn Process resource owner".to_owned(),
                        detail: err.to_string(),
                        source: error_source(err),
                    });
                }
            }
        }
        let response =
            match dispatch_request(state, &peer, request) {
                Ok(value) => value,
                Err(error) => serde_json::to_value(d2bd_runtime::wire::error_frame(&error))
                    .map_err(|err| TypedError::InternalIo {
                        context: "serialize error response".to_owned(),
                        detail: err.to_string(),
                        source: error_source(err),
                    })?,
            };
        write_json_frame(&stream, &response)?;
    }
}

fn dispatch_request(
    state: &ServerState,
    peer: &PeerIdentity,
    request: d2bd_runtime::wire::Request,
) -> Result<Value, TypedError> {
    let verb = request.verb_name();
    if matches!(peer.role, PeerRole::HostShutdown) && !verb_allowed_for_host_shutdown(verb) {
        return Err(TypedError::AuthzNotAdmin {
            verb: verb.to_owned(),
        });
    }
    if verb_requires_admin(verb) && !matches!(peer.role, PeerRole::Admin | PeerRole::HostShutdown) {
        return Err(TypedError::AuthzNotAdmin {
            verb: verb.to_owned(),
        });
    }
    match &request {
        d2bd_runtime::wire::Request::VmStop(lifecycle)
        | d2bd_runtime::wire::Request::VmRestart(lifecycle)
            if vm_lifecycle_force_requested(lifecycle) =>
        {
            note_force_shutdown_request(state, &lifecycle.vm);
        }
        _ => {}
    }
    // Acquire the op lock for this verb ONCE, here at the dispatch
    // boundary on the worker thread (never the accept loop). Read-only
    // verbs take no lock; per-VM mutating verbs serialize on the VM; a
    // global verb is mutually exclusive with all per-VM ops. The guard is
    // held across the whole op (DAG + rollback + cleanup); inner
    // stop/start helpers invoked by restart/rollback do NOT re-acquire it,
    // so there is no nested self-deadlock.
    let invalidates_status_model = request_invalidates_public_status_model(&request);
    let _op_lock = state.op_locks.acquire(&request.lock_class());
    let result = dispatch_request_locked(state, peer, request);
    if invalidates_status_model {
        state.public_status_read_model.invalidate();
    }
    result
}

/// Verb dispatch body executed under the op lock already acquired by
/// [`dispatch_request`]. Restart/rollback paths call the inner
/// `dispatch_broker_*` helpers directly (never re-entering
/// `dispatch_request`), so the lock is held exactly once for the op.
fn dispatch_request_locked(
    state: &ServerState,
    peer: &PeerIdentity,
    request: d2bd_runtime::wire::Request,
) -> Result<Value, TypedError> {
    match request {
        d2bd_runtime::wire::Request::List(request) => dispatch_list(state, request),
        d2bd_runtime::wire::Request::Status(request) => {
            dispatch_status_as(state, broker_caller_role_for_peer(peer), request)
        }
        d2bd_runtime::wire::Request::Audit(request) => dispatch_audit(state, peer, request),
        d2bd_runtime::wire::Request::AuthStatus => Ok(dispatch_auth_status(state, peer)),
        // Mutating-verb apply dispatch is now fully direct. The backlog
        // verbs route from these request arms straight to their
        // `dispatch_broker_<verb>` helpers.
        //
        // The old shared `dispatch_mutating_verb` split no longer
        // applies in d2bd; only `mutating_verb_preflight` remains
        // to emit the typed InvalidRequest / dry-run-planned envelope
        // before apply dispatch runs.
        d2bd_runtime::wire::Request::VmStart(req) => {
            dispatch_broker_vm_start_as(state, req, broker_caller_role_for_peer(peer))
        }
        d2bd_runtime::wire::Request::VmStop(req) => {
            dispatch_broker_vm_stop_as(state, req, broker_caller_role_for_peer(peer))
        }
        d2bd_runtime::wire::Request::VmRestart(req) => {
            dispatch_broker_vm_restart_as(state, req, broker_caller_role_for_peer(peer))
        }
        d2bd_runtime::wire::Request::Switch(req) => {
            dispatch_broker_switch_as(state, broker_caller_role_for_peer(peer), req)
        }
        d2bd_runtime::wire::Request::Boot(req) => {
            dispatch_broker_boot_as(state, broker_caller_role_for_peer(peer), req)
        }
        d2bd_runtime::wire::Request::Test(req) => {
            dispatch_broker_test_as(state, broker_caller_role_for_peer(peer), req)
        }
        d2bd_runtime::wire::Request::Rollback(req) => {
            dispatch_broker_rollback_as(state, broker_caller_role_for_peer(peer), req)
        }
        d2bd_runtime::wire::Request::UsbipBind(req) => {
            dispatch_broker_usbip_bind(state, broker_caller_role_for_peer(peer), req)
        }
        d2bd_runtime::wire::Request::UsbipUnbind(req) => {
            dispatch_broker_usbip_unbind(state, broker_caller_role_for_peer(peer), req)
        }
        d2bd_runtime::wire::Request::UsbipProbe => {
            dispatch_broker_usbip_probe(state, broker_caller_role_for_peer(peer))
        }
        d2bd_runtime::wire::Request::HostPrepare(req) => {
            dispatch_broker_host_prepare_as(state, req, broker_caller_role_for_peer(peer))
        }
        d2bd_runtime::wire::Request::HostDestroy(req) => {
            dispatch_broker_host_destroy_as(state, req, broker_caller_role_for_peer(peer))
        }
        d2bd_runtime::wire::Request::HostReconcile(req) => {
            dispatch_broker_host_reconcile_as(state, req, broker_caller_role_for_peer(peer))
        }
        d2bd_runtime::wire::Request::Console(op) => dispatch_console(state, peer, op),
        d2bd_runtime::wire::Request::Workload(op) => dispatch_workload(state, peer, op),
        d2bd_runtime::wire::Request::Audio(op) => {
            if !matches!(op, public_wire::AudioOp::Status(_))
                && !matches!(peer.role, PeerRole::Admin)
            {
                return Err(TypedError::AuthzNotAdmin {
                    verb: "audio".to_owned(),
                });
            }
            audio_dispatch::dispatch_audio(state, broker_caller_role_for_peer(peer), op)
        }
        d2bd_runtime::wire::Request::Resource(request) => {
            dispatch_resource_request(state, peer, request)
        }
    }
}

fn process_resource_owner_request(request: &Value) -> bool {
    request.get("resourceType").and_then(Value::as_str) == Some("EphemeralProcess")
        && matches!(
            request.get("method").and_then(Value::as_str),
            Some("Create" | "Attach")
        )
        && request.get("sessionVerb").and_then(Value::as_str) == Some("attach")
}

fn process_resource_ref(request: &Value) -> Option<ResourceRef> {
    request
        .get("resourceRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|resource| resource.resource_type().as_str() == "EphemeralProcess")
        .or_else(|| {
            request
                .get("opId")
                .and_then(Value::as_u64)
                .and_then(|op_id| {
                    ResourceRef::parse(&format!("EphemeralProcess/exec-{op_id}")).ok()
                })
        })
        .or_else(|| {
            request
                .get("requestId")
                .and_then(Value::as_str)
                .and_then(|request_id| {
                    let name = format!("EphemeralProcess/exec-{}", shell_ref_digest(&[request_id]));
                    ResourceRef::parse(&name).ok()
                })
        })
        .or_else(|| {
            request
                .get("name")
                .and_then(Value::as_str)
                .and_then(|name| ResourceRef::parse(&format!("EphemeralProcess/{name}")).ok())
        })
        .or_else(|| {
            request
                .get("command")
                .and_then(Value::as_array)
                .and_then(|command| {
                    let command = command.iter().filter_map(Value::as_str).collect::<Vec<_>>();
                    let name = format!("EphemeralProcess/exec-{}", shell_ref_digest(&command));
                    ResourceRef::parse(&name).ok()
                })
        })
}

fn process_resource_management_request(request: &Value) -> bool {
    request.get("resourceType").and_then(Value::as_str) == Some("EphemeralProcess")
        && matches!(
            request.get("method").and_then(Value::as_str),
            Some("List" | "Status" | "Logs" | "Kill")
        )
}

fn process_resource_detached_create_request(request: &Value) -> bool {
    request.get("resourceType").and_then(Value::as_str) == Some("EphemeralProcess")
        && request.get("method").and_then(Value::as_str) == Some("Create")
        && request.get("sessionVerb").and_then(Value::as_str) != Some("attach")
}

fn map_resource_exec_error(error: exec_session::ExecOpError, vm: &str) -> TypedError {
    match error {
        exec_session::ExecOpError::Auth => TypedError::AuthzNotAdmin {
            verb: "exec".to_owned(),
        },
        exec_session::ExecOpError::Capability | exec_session::ExecOpError::DetachedUnavailable => {
            TypedError::RuntimeCapabilityUnsupported {
                vm: vm.to_owned(),
                runtime_kind: "component-session".to_owned(),
                capability: "process-attach".to_owned(),
                verb: "exec".to_owned(),
            }
        }
        exec_session::ExecOpError::Timeout => TypedError::ProcessExecFailed {
            kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Timeout,
        },
        exec_session::ExecOpError::Transport => TypedError::ProcessExecFailed {
            kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Transport,
        },
        exec_session::ExecOpError::StaleSession | exec_session::ExecOpError::OldGeneration => {
            TypedError::ProcessExecFailed {
                kind: d2bd_runtime::typed_error::ProcessExecErrorKind::OldGeneration,
            }
        }
        exec_session::ExecOpError::Protocol | exec_session::ExecOpError::Guest(_) => {
            TypedError::ProcessExecFailed {
                kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
            }
        }
    }
}

fn establish_error_as_exec_error(
    error: exec_session::ExecEstablishError,
) -> exec_session::ExecOpError {
    match error {
        exec_session::ExecEstablishError::Transport => exec_session::ExecOpError::Transport,
        exec_session::ExecEstablishError::Auth => exec_session::ExecOpError::Auth,
        exec_session::ExecEstablishError::Protocol => exec_session::ExecOpError::Protocol,
        exec_session::ExecEstablishError::Timeout => exec_session::ExecOpError::Timeout,
        exec_session::ExecEstablishError::OldGeneration => exec_session::ExecOpError::OldGeneration,
        exec_session::ExecEstablishError::Capability => exec_session::ExecOpError::Capability,
        exec_session::ExecEstablishError::Guest(inner) => exec_session::ExecOpError::Guest(inner),
    }
}

fn process_resource_execution_ref(request: &Value) -> Result<(String, ResourceRef), TypedError> {
    let execution_ref = request
        .get("executionRef")
        .and_then(Value::as_str)
        .ok_or(TypedError::ProcessExecFailed {
            kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
        })?;
    let execution_ref =
        ResourceRef::parse(execution_ref).map_err(|_| TypedError::ProcessExecFailed {
            kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
        })?;
    let vm = execution_ref.name().as_str().to_owned();
    if execution_ref.resource_type().as_str() != "Guest" {
        return Err(TypedError::RuntimeCapabilityUnsupported {
            vm,
            runtime_kind: "component-session".to_owned(),
            capability: "process-attach".to_owned(),
            verb: "exec".to_owned(),
        });
    }
    Ok((vm, execution_ref))
}

fn process_resource_execution_ref_from_resource(
    state: &ServerState,
    request: &Value,
) -> Result<(String, ResourceRef), TypedError> {
    let zone = request
        .get("zoneRef")
        .and_then(Value::as_str)
        .and_then(|value| value.strip_prefix("Zone/"))
        .and_then(|value| ZoneId::parse(value.to_owned()).ok())
        .ok_or(TypedError::ProcessExecFailed {
            kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
        })?;
    let process_ref = request
        .get("resourceRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|value| value.resource_type().as_str() == "EphemeralProcess")
        .ok_or(TypedError::ProcessExecFailed {
            kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
        })?;
    let client = state
        .resource_plane
        .try_lock()
        .ok()
        .and_then(|plane| plane.clone())
        .and_then(|plane| plane.zone(&zone).ok())
        .and_then(|runtime| runtime.process_resource_client())
        .ok_or_else(|| TypedError::RuntimeCapabilityUnsupported {
            vm: process_ref.name().as_str().to_owned(),
            runtime_kind: "component-session".to_owned(),
            capability: "process-attach".to_owned(),
            verb: "exec".to_owned(),
        })?;
    let mut target = DaemonShellAuthority::shell_resource_identity(&zone, &process_ref);
    target.resource_type = "EphemeralProcess".to_owned();
    let mut projection = resource_wire::Projection::new();
    projection.kind =
        protobuf::EnumOrUnknown::new(resource_wire::ProjectionKind::PROJECTION_KIND_FULL);
    let mut get = resource_wire::GetRequest::new();
    get.meta = protobuf::MessageField::some(DaemonShellAuthority::shell_resource_request_meta(
        "process-resource-resolve-target",
    ));
    get.target = protobuf::MessageField::some(target);
    get.projection = protobuf::MessageField::some(projection);
    let response = drive_sync(&state.runtime_handle, client.get(get));
    let resource = response.resource.as_ref().ok_or_else(|| {
        response
            .error
            .as_ref()
            .map(|error| {
                map_resource_exec_error(resource_error_to_op(error), process_ref.name().as_str())
            })
            .unwrap_or_else(|| TypedError::ProcessExecFailed {
                kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
            })
    })?;
    let envelope = d2b_contracts_resource::v3::ResourceEnvelope::from_json(
        &resource.canonical_json,
    )
    .map_err(|_| TypedError::ProcessExecFailed {
        kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
    })?;
    if envelope.resource_type().as_str() != "EphemeralProcess" {
        return Err(TypedError::ProcessExecFailed {
            kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
        });
    }
    let spec = envelope.spec().base().to_canonical_bytes();
    let spec: Value = serde_json::from_slice(&spec).map_err(|_| TypedError::ProcessExecFailed {
        kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
    })?;
    let execution_ref = spec
        .get("executionRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|value| matches!(value.resource_type().as_str(), "Host" | "Guest"))
        .ok_or(TypedError::ProcessExecFailed {
            kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
        })?;
    Ok((execution_ref.name().as_str().to_owned(), execution_ref))
}

fn dispatch_resource_exec_request(
    state: &ServerState,
    peer: &PeerIdentity,
    request: &Value,
) -> Result<Value, TypedError> {
    if !matches!(peer.role, PeerRole::Admin) {
        return Err(TypedError::AuthzNotAdmin {
            verb: "exec".to_owned(),
        });
    }
    let (vm, execution_ref) = if request.get("executionRef").is_some() {
        process_resource_execution_ref(request)?
    } else {
        process_resource_execution_ref_from_resource(state, request)?
    };
    let client = exec_detached::ResourceDetachedClient::new(
        production_process_resource_port(state, request, &execution_ref),
        execution_ref,
    )
    .map_err(|error| map_resource_exec_error(error, &vm))?;
    let process_ref = request
        .get("resourceRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok());
    let method = request.get("method").and_then(Value::as_str);
    let response = match method {
        Some("List") => {
            let result = drive_sync(&state.runtime_handle, client.list())
                .map_err(|error| map_resource_exec_error(error, &vm))?;
            public_wire::ExecOpResponse::List(result)
        }

        Some("Status") => {
            let process_ref = process_ref.ok_or(TypedError::ProcessExecFailed {
                kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
            })?;
            let result = drive_sync(&state.runtime_handle, client.status(&process_ref))
                .map_err(|error| map_resource_exec_error(error, &vm))?;
            public_wire::ExecOpResponse::Status(result)
        }
        Some("Logs") => {
            let process_ref = process_ref.ok_or(TypedError::ProcessExecFailed {
                kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
            })?;
            let stdout_offset = request.get("stdoutOffset").and_then(Value::as_u64);
            let stderr_offset = request.get("stderrOffset").and_then(Value::as_u64);
            let max_len = request.get("maxLen").and_then(Value::as_u64);
            let result =
                drive_sync(&state.runtime_handle, client.logs(&process_ref, stdout_offset, stderr_offset, max_len))
                    .map_err(|error| map_resource_exec_error(error, &vm))?;
            public_wire::ExecOpResponse::Logs(result)
        }
        Some("Kill") => {
            let process_ref = process_ref.ok_or(TypedError::ProcessExecFailed {
                kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
            })?;
            let result = drive_sync(&state.runtime_handle, client.kill(&process_ref))
                .map_err(|error| map_resource_exec_error(error, &vm))?;
            public_wire::ExecOpResponse::Kill(result)
        }
        _ => {
            return Err(TypedError::ProcessExecFailed {
                kind: d2bd_runtime::typed_error::ProcessExecErrorKind::Protocol,
            });
        }
    };
    Ok(d2bd_runtime::wire::exec_response(&response))
}

fn dispatch_resource_exec_create_request(
    state: &ServerState,
    peer: &PeerIdentity,
    request: &Value,
) -> Result<Value, TypedError> {
    if !matches!(peer.role, PeerRole::Admin | PeerRole::Launcher) {
        return Err(TypedError::AuthzNotAdmin {
            verb: "exec".to_owned(),
        });
    }
    let (vm, execution_ref) = process_resource_execution_ref(request)?;
    let spec = exec_session::ExecStartSpec {
        vm: vm.clone(),
        request_id: request
            .get("opId")
            .and_then(Value::as_u64)
            .map(|value| value.to_string())
            .or_else(|| {
                request
                    .get("requestId")
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned)
            }),
        argv: request
            .get("argv")
            .and_then(Value::as_array)
            .map(|argv| {
                argv.iter()
                    .filter_map(Value::as_str)
                    .map(ToOwned::to_owned)
                    .collect()
            })
            .or_else(|| {
                request
                    .get("command")
                    .and_then(Value::as_array)
                    .map(|argv| {
                        argv.iter()
                            .filter_map(Value::as_str)
                            .map(ToOwned::to_owned)
                            .collect()
                    })
            })
            .unwrap_or_default(),
        tty: false,
        detached: true,
        env: request
            .get("env")
            .and_then(Value::as_array)
            .map(|env| {
                env.iter()
                    .filter_map(Value::as_str)
                    .filter_map(|value| value.split_once('='))
                    .map(|(key, value)| (key.to_owned(), value.to_owned()))
                    .collect()
            })
            .unwrap_or_default(),
        cwd: request
            .get("cwd")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned),
        term_size: None,
    };
    let client = exec_detached::ResourceDetachedClient::new(
        production_process_resource_port(state, request, &execution_ref),
        execution_ref,
    )
    .map_err(|error| map_resource_exec_error(error, &vm))?;
    let result = drive_sync(&state.runtime_handle, client.create(&spec))
        .map_err(|error| map_resource_exec_error(error, &vm))?;
    Ok(d2bd_runtime::wire::exec_response(
        &public_wire::ExecOpResponse::DetachedCreate(result),
    ))
}

fn dispatch_config_nixos_service_request(
    state: &ServerState,
    peer: &PeerIdentity,
    request: &Value,
) -> Result<Value, TypedError> {
    if !matches!(peer.role, PeerRole::Admin) {
        return Err(TypedError::AuthzNotAdmin {
            verb: "config-nixos".to_owned(),
        });
    }
    if request.get("sessionVerb").and_then(Value::as_str) != Some("invoke") {
        return Err(TypedError::WireInvalidFrame {
            detail: "config-nixos service requires the invoke session verb".to_owned(),
        });
    }
    let zone = request
        .get("zoneRef")
        .and_then(Value::as_str)
        .and_then(|value| value.strip_prefix("Zone/"))
        .and_then(|value| ZoneId::parse(value).ok())
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "config-nixos request has an invalid Zone reference".to_owned(),
        })?;
    let method = request
        .get("method")
        .and_then(Value::as_str)
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "config-nixos request is missing method".to_owned(),
        })?;
    let operation = d2b_provider_config_nixos::ConfigOperation::ALL
        .into_iter()
        .find(|candidate| candidate.as_str() == method)
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "config-nixos service operation is not supported on the operator route"
                .to_owned(),
        })?;
    let payload = config_nixos_payload(request)?;
    let service = d2b_provider_config_nixos::ConfigService;
    service
        .validate_operation(operation, &payload)
        .map_err(config_nixos_wire_error)?;
    let guest_ref = payload
        .get("guestRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|resource| resource.resource_type().as_str() == "Guest")
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "config-nixos request has an invalid Guest reference".to_owned(),
        })?;
    let plane = state
        .resource_plane
        .try_lock()
        .map_err(|_| TypedError::InternalConfig {
            detail: "resource plane unavailable".to_owned(),
            source: None,
        })?
        .clone()
        .ok_or_else(|| TypedError::InternalConfig {
            detail: "resource plane unavailable".to_owned(),
            source: None,
        })?;
    let runtime = plane.zone(&zone).map_err(|_| TypedError::InternalConfig {
        detail: "config-nixos Zone runtime unavailable".to_owned(),
        source: None,
    })?;
    let guest_lookup = json!({
        "zoneRef": format!("Zone/{}", zone.as_str()),
        "service": "d2b.resource.v3",
        "method": "Get",
        "resourceRef": guest_ref.to_canonical_string(),
    });
    let guest = drive_sync(&state.runtime_handle, runtime.dispatch_public_cli_request(&guest_lookup, peer.uid))
        .map_err(|_| TypedError::InternalConfig {
            detail: "config-nixos Guest lookup failed".to_owned(),
            source: None,
        })?;
    if guest.get("kind").is_some() {
        return Err(TypedError::AuthzNotAdmin {
            verb: "config-nixos Guest is not in the requested Zone".to_owned(),
        });
    }

    match operation {
        d2b_provider_config_nixos::ConfigOperation::ReadGuestConfig => {
            let sync: d2b_provider_config_nixos::ConfigSyncRequest =
                serde_json::from_value(payload).map_err(|_| TypedError::WireInvalidFrame {
                    detail: "config-nixos read request is malformed".to_owned(),
                })?;
            let response = read_guest_config_typed(state, &zone, sync.guest_ref.name().as_str())?;
            serde_json::to_value(response).map_err(|_| TypedError::WireInvalidFrame {
                detail: "config-nixos response encoding failed".to_owned(),
            })
        }
        d2b_provider_config_nixos::ConfigOperation::Stage => {
            let stage: d2b_provider_config_nixos::ConfigStageRequest =
                serde_json::from_value(payload).map_err(|_| TypedError::WireInvalidFrame {
                    detail: "config-nixos stage request is malformed".to_owned(),
                })?;
            let response = state
                .config_staging
                .try_lock()
                .map_err(|_| TypedError::InternalConfig {
                    detail: "config staging state unavailable".to_owned(),
                    source: None,
                })?
                .stage(
                    d2b_provider_config_nixos::ConfigCaller::Admin,
                    &zone,
                    &stage,
                )
                .map_err(config_nixos_wire_error)?;
            serde_json::to_value(response).map_err(|_| TypedError::WireInvalidFrame {
                detail: "config-nixos stage response encoding failed".to_owned(),
            })
        }
        d2b_provider_config_nixos::ConfigOperation::Diff => {
            let diff: d2b_provider_config_nixos::ConfigDiffRequest =
                serde_json::from_value(payload).map_err(|_| TypedError::WireInvalidFrame {
                    detail: "config-nixos diff request is malformed".to_owned(),
                })?;
            let response = state
                .config_staging
                .try_lock()
                .map_err(|_| TypedError::InternalConfig {
                    detail: "config staging state unavailable".to_owned(),
                    source: None,
                })?
                .diff(d2b_provider_config_nixos::ConfigCaller::Admin, &zone, &diff)
                .map_err(config_nixos_wire_error)?;
            serde_json::to_value(response).map_err(|_| TypedError::WireInvalidFrame {
                detail: "config-nixos diff response encoding failed".to_owned(),
            })
        }
        d2b_provider_config_nixos::ConfigOperation::Approve => {
            let approve: d2b_provider_config_nixos::ConfigApproveRequest =
                serde_json::from_value(payload).map_err(|_| TypedError::WireInvalidFrame {
                    detail: "config-nixos approve request is malformed".to_owned(),
                })?;
            let response = state
                .config_staging
                .try_lock()
                .map_err(|_| TypedError::InternalConfig {
                    detail: "config staging state unavailable".to_owned(),
                    source: None,
                })?
                .approve(
                    d2b_provider_config_nixos::ConfigCaller::Admin,
                    &zone,
                    &approve,
                )
                .map_err(config_nixos_wire_error)?;
            serde_json::to_value(response).map_err(|_| TypedError::WireInvalidFrame {
                detail: "config-nixos approve response encoding failed".to_owned(),
            })
        }
        d2b_provider_config_nixos::ConfigOperation::Reject => {
            let reject: d2b_provider_config_nixos::ConfigRejectRequest =
                serde_json::from_value(payload).map_err(|_| TypedError::WireInvalidFrame {
                    detail: "config-nixos reject request is malformed".to_owned(),
                })?;
            let response = state
                .config_staging
                .try_lock()
                .map_err(|_| TypedError::InternalConfig {
                    detail: "config staging state unavailable".to_owned(),
                    source: None,
                })?
                .reject(
                    d2b_provider_config_nixos::ConfigCaller::Admin,
                    &zone,
                    &reject,
                )
                .map_err(config_nixos_wire_error)?;
            serde_json::to_value(response).map_err(|_| TypedError::WireInvalidFrame {
                detail: "config-nixos reject response encoding failed".to_owned(),
            })
        }
        d2b_provider_config_nixos::ConfigOperation::Status => {
            let status: d2b_provider_config_nixos::ConfigStatusRequest =
                serde_json::from_value(payload).map_err(|_| TypedError::WireInvalidFrame {
                    detail: "config-nixos status request is malformed".to_owned(),
                })?;
            let response = state
                .config_staging
                .try_lock()
                .map_err(|_| TypedError::InternalConfig {
                    detail: "config staging state unavailable".to_owned(),
                    source: None,
                })?
                .status(
                    d2b_provider_config_nixos::ConfigCaller::Admin,
                    &zone,
                    &status,
                )
                .map_err(config_nixos_wire_error)?;
            serde_json::to_value(response).map_err(|_| TypedError::WireInvalidFrame {
                detail: "config-nixos status response encoding failed".to_owned(),
            })
        }
    }
}

fn config_nixos_payload(request: &Value) -> Result<Value, TypedError> {
    let mut payload = request
        .as_object()
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "config-nixos request must be an object".to_owned(),
        })?
        .clone();
    for key in [
        "type",
        "method",
        "zoneRef",
        "schemaVersion",
        "service",
        "sessionVerb",
    ] {
        payload.remove(key);
    }
    Ok(Value::Object(payload))
}

fn config_nixos_wire_error(error: d2b_provider_config_nixos::ConfigError) -> TypedError {
    TypedError::WireInvalidFrame {
        detail: error.code().to_owned(),
    }
}

fn dispatch_resource_request(
    state: &ServerState,
    peer: &PeerIdentity,
    request: d2bd_runtime::wire::ResourceRequest,
) -> Result<Value, TypedError> {
    if !matches!(peer.role, PeerRole::Admin | PeerRole::Launcher) {
        return Ok(resource_runtime_error_frame(
            resource_runtime::ResourceRuntimeError::AuthenticationUnavailable,
        ));
    }
    if [
        "subject",
        "subjectRef",
        "subjectUid",
        "principal",
        "principalRef",
        "role",
        "uid",
        "user",
        "userRef",
    ]
    .iter()
    .any(|field| request.value().get(*field).is_some())
    {
        return Ok(resource_runtime_error_frame(
            resource_runtime::ResourceRuntimeError::RequestInvalid,
        ));
    }
    let method = request.method().unwrap_or("Resource");
    if matches!(peer.role, PeerRole::HostShutdown) && method != "Stop" {
        return Ok(resource_runtime_error_frame(
            resource_runtime::ResourceRuntimeError::AuthenticationUnavailable,
        ));
    }
    let runtime = match resolve_resource_runtime(state, &request.value()) {
        Ok(runtime) => runtime,
        Err(error) => return Ok(resource_runtime_error_frame(error)),
    };
    let gateway_route = match classify_gateway_zone_request(state, &runtime, &request.value()) {
        Ok(route) => route,
        Err(error) => return Ok(resource_runtime_error_frame(error)),
    };
    if gateway_route == GatewayZoneRequestRoute::Forward {
        match admit_gateway_zone_request(state, &runtime, &request.value(), peer.uid) {
            Ok(value) => return Ok(value),
            Err(error) => return Ok(resource_runtime_error_frame(error)),
        }
    }
    if matches!(request.method(), Some("Start" | "Stop" | "Restart")) {
        let resource_type = request
            .value()
            .get("resourceRef")
            .and_then(Value::as_str)
            .and_then(|value| ResourceRef::parse(value).ok())
            .map(|value| value.resource_type().as_str().to_owned());
        return match resource_type.as_deref() {
            Some("Guest") => {
                dispatch_guest_lifecycle_resource_request(state, peer, runtime, &request.value())
            }
            Some("Process") => {
                dispatch_process_lifecycle_resource_request(&state.runtime_handle, peer, runtime, &request.value())
            }
            _ => Err(TypedError::WireInvalidFrame {
                detail: "lifecycle requires a Guest or Process resourceRef".to_owned(),
            }),
        };
    }
    if request.value().get("service").and_then(Value::as_str)
        == Some(d2b_provider_config_nixos::SERVICE_PACKAGE)
    {
        return dispatch_config_nixos_service_request(state, peer, &request.value());
    }
    if matches!(
        request.method(),
        Some("DeviceUsbAttach" | "DeviceUsbDetach" | "DeviceUsbProbe")
    ) {
        return dispatch_device_usb_resource_request(state, peer, &request.value());
    }
    if process_resource_detached_create_request(&request.value()) {
        return dispatch_resource_exec_create_request(state, peer, &request.value());
    }
    if process_resource_management_request(&request.value()) {
        return dispatch_resource_exec_request(state, peer, &request.value());
    }
    let typed_shell = typed_shell_resource_request(&request.value());
    let runtime = match if typed_shell {
        resolve_typed_shell_runtime(state, &request.value())
    } else {
        resolve_resource_runtime(state, &request.value())
    } {
        Ok(runtime) => runtime,
        Err(error) => {
            tracing::warn!(
                error = error.code(),
                method = ?request.method(),
                zone_ref = ?request.value().get("zoneRef"),
                resource_type = ?request.value().get("resourceType"),
                resource_ref = ?request.value().get("resourceRef"),
                "resource request runtime resolution refused"
            );
            return Ok(resource_runtime_error_frame(error));
        }
    };
    if typed_shell {
        return Ok(
            dispatch_typed_shell_resource_request(state, peer, &request.value())
                .unwrap_or_else(|error| typed_shell_resource_error_frame(&error)),
        );
    }

    // Admission has authenticated this local peer with SO_PEERCRED and
    // assigned its daemon role. The runtime binds that credential into the
    // request-scoped ComponentSession subject before invoking Resource API.
    match drive_sync(&state.runtime_handle, runtime.dispatch_public_cli_request(&request.value(), peer.uid)) {
        Ok(value) => Ok(value),
        Err(error) => {
            tracing::warn!(
                zone = %runtime.zone().as_str(),
                method,
                peer_uid = peer.uid,
                error = ?error,
                "public Resource request failed",
            );
            Ok(resource_runtime_error_frame(error))
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GatewayZoneRequestRoute {
    Local,
    HostControl,
    Forward,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GatewayZonePresence {
    Local,
    Composed,
    Refused,
}

fn classify_gateway_zone_request(
    state: &ServerState,
    runtime: &resource_runtime::ZoneResourceRuntime,
    request: &Value,
) -> Result<GatewayZoneRequestRoute, resource_runtime::ResourceRuntimeError> {
    let plane = state
        .resource_plane
        .try_lock()
        .ok()
        .and_then(|plane| plane.clone())
        .ok_or(resource_runtime::ResourceRuntimeError::PlaneUnavailable)?;
    let presence = if plane.gateway_zone_link_is_refused(runtime.zone()) {
        GatewayZonePresence::Refused
    } else if plane.gateway_zone_link(runtime.zone()).is_some() {
        GatewayZonePresence::Composed
    } else {
        GatewayZonePresence::Local
    };
    classify_gateway_zone_request_kind(presence, request)
}

fn classify_gateway_zone_request_kind(
    presence: GatewayZonePresence,
    request: &Value,
) -> Result<GatewayZoneRequestRoute, resource_runtime::ResourceRuntimeError> {
    let method = request
        .get("method")
        .and_then(Value::as_str)
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    if is_zone_link_control_request(request) {
        if gateway_zone_link_control_method(method) {
            return Ok(GatewayZoneRequestRoute::HostControl);
        }
        return Err(resource_runtime::ResourceRuntimeError::CapabilityUnavailable);
    }
    match presence {
        GatewayZonePresence::Local => Ok(GatewayZoneRequestRoute::Local),
        GatewayZonePresence::Composed if gateway_forwardable_request(request) => {
            Ok(GatewayZoneRequestRoute::Forward)
        }
        GatewayZonePresence::Composed => {
            Err(resource_runtime::ResourceRuntimeError::CapabilityUnavailable)
        }
        GatewayZonePresence::Refused => {
            Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable)
        }
    }
}

fn gateway_zone_link_control_method(method: &str) -> bool {
    matches!(
        method,
        "Get" | "List" | "Create" | "UpdateSpec" | "UpdateStatus" | "UpdateFinalizers" | "Delete"
    )
}

fn gateway_forwardable_method(method: &str) -> bool {
    gateway_zone_link_control_method(method)
}

fn gateway_forwardable_request(request: &Value) -> bool {
    let Some(method) = request.get("method").and_then(Value::as_str) else {
        return false;
    };
    gateway_forwardable_method(method)
        && !matches!(method, "Start" | "Stop" | "Restart" | "Reconcile")
        && !matches!(
            method,
            "DeviceUsbAttach" | "DeviceUsbDetach" | "DeviceUsbProbe"
        )
        && request.get("service").and_then(Value::as_str)
            != Some(d2b_provider_config_nixos::SERVICE_PACKAGE)
        && !process_resource_owner_request(request)
        && !process_resource_detached_create_request(request)
        && !process_resource_management_request(request)
        && !is_gateway_shell_resource_request(request)
        && !is_gateway_ephemeral_process_request(request)
}

fn is_gateway_shell_resource_request(request: &Value) -> bool {
    request.get("resourceType").and_then(Value::as_str)
        == Some("shell-terminal.d2bus.org.ShellSession")
        || request
            .get("resourceRef")
            .and_then(Value::as_str)
            .is_some_and(is_typed_shell_resource_ref)
}

fn is_gateway_ephemeral_process_request(request: &Value) -> bool {
    request.get("resourceType").and_then(Value::as_str) == Some("EphemeralProcess")
        || request
            .get("resourceRef")
            .and_then(Value::as_str)
            .and_then(|value| ResourceRef::parse(value).ok())
            .is_some_and(|value| value.resource_type().as_str() == "EphemeralProcess")
}

fn admit_gateway_zone_request(
    state: &ServerState,
    runtime: &resource_runtime::ZoneResourceRuntime,
    request: &Value,
    peer_uid: u32,
) -> Result<Value, resource_runtime::ResourceRuntimeError> {
    let plane = state
        .resource_plane
        .try_lock()
        .ok()
        .and_then(|plane| plane.clone())
        .ok_or(resource_runtime::ResourceRuntimeError::PlaneUnavailable)?;
    if plane.gateway_zone_link_is_refused(runtime.zone()) {
        return Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable);
    }
    let composition = plane
        .gateway_zone_link(runtime.zone())
        .ok_or(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable)?;
    let gateway_guest = drive_sync(&state.runtime_handle, gateway_guest_for_provider(
        runtime,
        composition.transport_provider_ref(),
    ))
    .ok_or(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable)?;
    if composition
        .last_gateway_guest()
        .as_ref()
        .is_some_and(|previous| !previous.same_guest_identity(&gateway_guest))
    {
        if let Some(previous) = composition.last_gateway_guest() {
            drive_sync(&state.runtime_handle, invalidate_guest_component_session_for_guest(
                state, &previous,
            ));
        }
        composition
            .reset_gateway_guest_identity()
            .map_err(|error| {
                tracing::warn!(
                    error = ?error,
                    guest_ref = %gateway_guest.guest_ref(),
                    zone = %gateway_guest.zone().as_str(),
                    "gateway guest identity reset failed; gateway route request denied"
                );
                resource_runtime::ResourceRuntimeError::ProviderPathUnavailable
            })?;
    }
    if composition.gateway_guest().as_ref() != Some(&gateway_guest) {
        if composition.gateway_guest().is_some() {
            composition.fence_gateway_session();
        }
        composition.set_gateway_guest(gateway_guest.clone());
    }
    if !composition.has_gateway_session() {
        let session = drive_sync(&state.runtime_handle, connect_guest_component_session_for_guest(
            state,
            &gateway_guest,
        ))
        .map_err(|error| {
            tracing::warn!(
                error = %error,
                guest_ref = %gateway_guest.guest_ref(),
                zone = %gateway_guest.zone().as_str(),
                "guest component session connect failed; gateway route request denied"
            );
            resource_runtime::ResourceRuntimeError::ProviderPathUnavailable
        })?;
        composition
            .bind_gateway_session(Arc::clone(&session))
            .map_err(|error| {
                tracing::warn!(
                    error = ?error,
                    guest_ref = %gateway_guest.guest_ref(),
                    zone = %gateway_guest.zone().as_str(),
                    "gateway session bind failed; gateway route request denied"
                );
                resource_runtime::ResourceRuntimeError::ProviderPathUnavailable
            })?;
        // U13: this session generation is now the realization authority for
        // Host-zone resources targeting the gateway Guest.
        bind_plane_guest_target(state, &session);
    }
    let gateway_guest_for_invalidation = gateway_guest.clone();
    let target_zone = composition.child_path().clone();
    let method = request
        .get("method")
        .and_then(Value::as_str)
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    let operation_id = gateway_route_operation_id(request, peer_uid, method);
    composition
        .admit_request(&operation_id, target_zone)
        .map_err(|error| {
            tracing::warn!(
                error = ?error,
                method = %method,
                "gateway route admission denied for child-zone request"
            );
            resource_runtime::ResourceRuntimeError::ProviderPathUnavailable
        })?;
    debug_assert!(gateway_forwardable_request(request));
    let session = composition
        .gateway_session()
        .ok_or(resource_runtime::ResourceRuntimeError::AuthenticationUnavailable)?;
    let result = drive_sync(&state.runtime_handle, runtime.dispatch_gateway_resource_request(
        &session,
        request,
        &operation_id,
    ));
    if matches!(
        &result,
        Err(
            resource_runtime::ResourceRuntimeError::ProviderPathUnavailable
                | resource_runtime::ResourceRuntimeError::AuthenticationUnavailable
        )
    ) {
        // U13/R21: the target went away - observed state becomes unavailable
        // while desired resources and assignments stay exactly as they are.
        unbind_plane_guest_target(state, &session);
        composition.fence_gateway_session();
        drive_sync(&state.runtime_handle, invalidate_guest_component_session_for_guest(
            state,
            &gateway_guest_for_invalidation,
        ));
    }
    result
}

/// Bind one authenticated guest session generation as the realization
/// authority of the Zone's target directory (U13, F5).
///
/// A failure here never denies gateway forwarding - it leaves the target path
/// unbound, which is the fail-closed direction: no Host-zone resource can
/// claim realization authority through this session.
fn bind_plane_guest_target(
    state: &ServerState,
    session: &Arc<d2bd_runtime::guest_component_session::GuestComponentSessionClient>,
) {
    let zone = session.identity().zone().as_str().to_owned();
    let plane = state
        .v3_planes
        .try_lock()
        .ok()
        .and_then(|planes| planes.get(&zone).map(std::sync::Arc::clone));
    let Some(plane) = plane else {
        tracing::warn!(zone = %zone, "guest target bind skipped: Zone v3 plane unavailable");
        return;
    };
    let Some(guest) = d2b_provider_guest::guest_target_ref(session.identity().guest_ref())
    else {
        tracing::warn!(zone = %zone, "guest target bind skipped: session subject is not a guest");
        return;
    };
    let generation = session.generation();
    let control = match d2b_provider_guest::session_target_control(
        crate::guest_target_session::DaemonGuestTargetSession::new(Arc::clone(session)),
        generation,
    ) {
        Ok(control) => control,
        Err(error) => {
            tracing::warn!(zone = %zone, error = %error, "guest target control unavailable");
            return;
        }
    };
    if let Err(error) = plane.bind_guest_target(&guest, generation, control) {
        tracing::warn!(zone = %zone, generation, error = %error, "guest target bind refused");
    }
}

/// Mark the guest target unavailable on the fencing path (U13, R21): the
/// desired resources and their assignments stay, only observed state becomes
/// unavailable, and a newer session is never torn down by a stale fence.
fn unbind_plane_guest_target(
    state: &ServerState,
    session: &Arc<d2bd_runtime::guest_component_session::GuestComponentSessionClient>,
) {
    let zone = session.identity().zone().as_str().to_owned();
    let plane = state
        .v3_planes
        .try_lock()
        .ok()
        .and_then(|planes| planes.get(&zone).map(std::sync::Arc::clone));
    let Some(plane) = plane else {
        return;
    };
    let Some(guest) = d2b_provider_guest::guest_target_ref(session.identity().guest_ref())
    else {
        return;
    };
    let _ = plane.unbind_guest_target(&guest, session.generation());
}

fn gateway_route_operation_id(request: &Value, peer_uid: u32, method: &str) -> String {
    let public_operation_id =
        d2bd_runtime::resource_runtime_support::public_operation_id(request, peer_uid, method);
    let target = request
        .get("resourceRef")
        .or_else(|| request.get("resourceType"))
        .and_then(Value::as_str)
        .unwrap_or("unaddressed");
    let zone = request
        .get("zoneRef")
        .and_then(Value::as_str)
        .unwrap_or("unaddressed");
    let digest = Sha256::digest(
        format!("d2b:gateway-route:v1:{peer_uid}:{public_operation_id}:{method}:{zone}:{target}")
            .as_bytes(),
    );
    format!(
        "gateway-route-{}",
        digest
            .iter()
            .take(16)
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    )
}

fn is_zone_link_control_request(request: &Value) -> bool {
    request.get("resourceType").and_then(Value::as_str) == Some("ZoneLink")
        || request
            .get("resourceRef")
            .and_then(Value::as_str)
            .and_then(|value| ResourceRef::parse(value).ok())
            .is_some_and(|value| value.resource_type().as_str() == "ZoneLink")
}

fn dispatch_guest_lifecycle_resource_request(
    state: &ServerState,
    peer: &PeerIdentity,
    runtime: Arc<resource_runtime::ZoneResourceRuntime>,
    request: &Value,
) -> Result<Value, TypedError> {
    let target = request
        .get("resourceRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|value| value.resource_type().as_str() == "Guest")
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "Guest lifecycle requires a Guest resourceRef".to_owned(),
        })?;
    let method = request
        .get("method")
        .and_then(Value::as_str)
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "Guest lifecycle request is missing method".to_owned(),
        })?;
    let operation = match method {
        "Start" => provider_effects::GuestLifecycleOperation::Start,
        "Stop" => provider_effects::GuestLifecycleOperation::Stop,
        "Restart" => provider_effects::GuestLifecycleOperation::Restart,
        _ => {
            return Err(TypedError::WireUnsupportedRequest {
                request_type: method.to_owned(),
            });
        }
    };
    let verb = format!("guest {}", method.to_ascii_lowercase());
    let mode = match mutation_mode_from_request(request, &verb) {
        Ok(mode) => mode,
        Err(response) => return Ok(response),
    };
    if let Some(response) = mutating_verb_preflight(&verb, mode, Some(target.name().as_str())) {
        return Ok(response);
    }
    let caller_role = broker_caller_role_for_peer(peer);
    let force = request
        .get("force")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let wait_for_ready = request
        .get("waitForReady")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let request_operation_id =
        d2bd_runtime::resource_runtime_support::public_operation_id(request, peer.uid, method);
    let base_operation_id = provider_registry::next_lifecycle_operation_id(
        operation.as_str(),
        target.name().as_str(),
        &request_operation_id,
    );
    let handle = state.runtime_handle.clone();
    let provider_ref = match drive_sync(&handle, runtime.guest_provider_ref(&target)) {
        Ok(provider_ref) => provider_ref,
        Err(error) => return Ok(resource_runtime_error_frame(error)),
    };
    let dispatch_one = |operation: provider_effects::GuestLifecycleOperation,
                        operation_id: &str|
     -> Result<
        (Value, Option<provider_effects::LifecycleAuthorization>),
        TypedError,
    > {
        let admission = match drive_sync(&handle, runtime.admit_guest_lifecycle(
            peer.uid,
            target.clone(),
            operation_id,
        )) {
            Ok(admission) => admission,
            Err(error) => return Ok((resource_runtime_error_frame(error), None)),
        };
        let authorization = match provider_effects::LifecycleAuthorization::from_lease(
            admission.lease,
            target.clone(),
            admission.guest_uid,
            admission.guest_generation,
            admission.provider_assignment_generation,
        ) {
            Ok(authorization) => authorization,
            Err(error) => {
                return Ok((
                    provider_lifecycle_failure_response(&verb, target.name().as_str(), error),
                    None,
                ));
            }
        };
        let effect = DaemonGuestLifecycleEffect {
            state,
            runtime: Arc::clone(&runtime),
            guest: target.clone(),
            caller_role: caller_role.clone(),
            force,
            wait_for_ready,
            operation,
            authorization: authorization.clone(),
        };
        let response = match state.provider_runtime.dispatch_v3_lifecycle(
            &caller_role,
            &provider_ref,
            target.clone(),
            (
                operation,
                operation_id.to_owned(),
                authorization.clone(),
            ),
            &effect,
        ) {
            Ok(provider_registry::ProviderRuntimeDispatch::Active(
                provider_effects::EffectDispatch::Dispatched(response),
            )) => response,
            Ok(provider_registry::ProviderRuntimeDispatch::Active(
                provider_effects::EffectDispatch::Duplicate,
            )) => applied_response(
                &verb,
                format!(
                    "guest {}: duplicate Provider lifecycle request",
                    target.name().as_str()
                ),
            ),
            Err(error) => provider_lifecycle_failure_response(&verb, target.name().as_str(), error),
        };
        Ok((response, Some(authorization)))
    };

    if operation == provider_effects::GuestLifecycleOperation::Restart {
        let stop_id = format!("{base_operation_id}:stop");
        let (stop, stop_authorization) =
            dispatch_one(provider_effects::GuestLifecycleOperation::Stop, &stop_id)?;
        if response_outcome(&stop) != Some("applied") {
            return Ok(retarget_mutating_response(&stop, &verb));
        }
        let Some(stop_authorization) = stop_authorization else {
            return Ok(retarget_mutating_response(
                &provider_lifecycle_failure_response(
                    &verb,
                    target.name().as_str(),
                    provider_effects::ProviderEffectError::StateUnavailable,
                ),
                &verb,
            ));
        };
        let stop_is_latest = match state.provider_runtime.lifecycle_admission_is_latest_v3(
            &caller_role,
            &provider_ref,
            provider_effects::GuestLifecycleOperation::Stop,
            &stop_authorization,
        ) {
            Ok(is_latest) => is_latest,
            Err(error) => {
                return Ok(retarget_mutating_response(
                    &provider_lifecycle_failure_response(&verb, target.name().as_str(), error),
                    &verb,
                ));
            }
        };
        if !stop_is_latest {
            return Ok(retarget_mutating_response(
                &provider_lifecycle_failure_response(
                    &verb,
                    target.name().as_str(),
                    provider_effects::ProviderEffectError::MutationPending,
                ),
                &verb,
            ));
        }
        let start_id = format!("{base_operation_id}:start");
        let (start, _) = dispatch_one(provider_effects::GuestLifecycleOperation::Start, &start_id)?;
        if response_outcome(&start) != Some("applied") {
            return Ok(retarget_mutating_response(&start, &verb));
        }
        return Ok(applied_response(
            &verb,
            format!(
                "guest {}: {}; {}",
                target.name().as_str(),
                response_summary(&stop).unwrap_or("stop applied"),
                response_summary(&start).unwrap_or("start applied"),
            ),
        ));
    }
    dispatch_one(operation, &base_operation_id).map(|(response, _)| response)
}

fn resource_runtime_failure(error: resource_runtime::ResourceRuntimeError) -> TypedError {
    TypedError::RuntimeCapabilityUnsupported {
        vm: "guest".to_owned(),
        runtime_kind: "component-session".to_owned(),
        capability: error.code().to_owned(),
        verb: "lifecycle".to_owned(),
    }
}

fn dispatch_process_lifecycle_resource_request(
    handle: &tokio::runtime::Handle,
    peer: &PeerIdentity,
    runtime: Arc<resource_runtime::ZoneResourceRuntime>,
    request: &Value,
) -> Result<Value, TypedError> {
    let target = request
        .get("resourceRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|value| value.resource_type().as_str() == "Process")
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "Process lifecycle requires a Process resourceRef".to_owned(),
        })?;
    let method = request
        .get("method")
        .and_then(Value::as_str)
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "Process lifecycle request is missing method".to_owned(),
        })?;
    let desired = match method {
        "Start" => "running",
        "Stop" => "stopped",
        "Restart" => "restart",
        _ => {
            return Err(TypedError::WireUnsupportedRequest {
                request_type: method.to_owned(),
            });
        }
    };
    let verb = format!("process {}", method.to_ascii_lowercase());
    let mode = match mutation_mode_from_request(request, &verb) {
        Ok(mode) => mode,
        Err(response) => return Ok(response),
    };
    if let Some(response) = mutating_verb_preflight(&verb, mode, Some(target.name().as_str())) {
        return Ok(response);
    }
    let base_operation_id =
        d2bd_runtime::resource_runtime_support::public_operation_id(request, peer.uid, method);
    let apply_one = |lifecycle: &str, operation_id: &str| -> Result<Value, TypedError> {
        let get_request = json!({
            "method": "Get",
            "service": "d2b.resource.v3",
            "zoneRef": format!("Zone/{}", runtime.zone().as_str()),
            "resourceRef": target.to_canonical_string(),
        });
        let current = drive_sync(handle, runtime.dispatch_public_cli_request(&get_request, peer.uid))
            .map_err(resource_runtime_failure)?;
        if current.get("type").and_then(Value::as_str) == Some("error") {
            return Ok(current);
        }
        let revision = current
            .pointer("/metadata/revision")
            .and_then(Value::as_u64)
            .ok_or_else(|| TypedError::WireInvalidFrame {
                detail: "Process lifecycle resource revision is missing".to_owned(),
            })?;
        let mut spec =
            current
                .get("spec")
                .cloned()
                .ok_or_else(|| TypedError::WireInvalidFrame {
                    detail: "Process lifecycle resource spec is missing".to_owned(),
                })?;
        spec.as_object_mut()
            .ok_or_else(|| TypedError::WireInvalidFrame {
                detail: "Process lifecycle resource spec is invalid".to_owned(),
            })?
            .insert(
                "desiredLifecycle".to_owned(),
                Value::String(lifecycle.to_owned()),
            );
        let update_request = json!({
            "method": "UpdateSpec",
            "service": "d2b.resource.v3",
            "zoneRef": format!("Zone/{}", runtime.zone().as_str()),
            "resourceRef": target.to_canonical_string(),
            "expectedRevision": revision,
            "operationId": operation_id,
            "spec": spec,
            "waitForReconcile": request.get("waitForReady").and_then(Value::as_bool).unwrap_or(true),
        });
        drive_sync(handle, runtime.dispatch_public_cli_request(&update_request, peer.uid))
            .map_err(resource_runtime_failure)
    };
    if desired == "restart" {
        let stop = apply_one("stopped", &format!("{base_operation_id}:stop"))?;
        if stop.get("type").and_then(Value::as_str) == Some("error") {
            return Ok(stop);
        }
        return apply_one("running", &format!("{base_operation_id}:start"));
    }
    apply_one(desired, &base_operation_id)
}

fn dispatch_device_usb_resource_request(
    state: &ServerState,
    peer: &PeerIdentity,
    request: &Value,
) -> Result<Value, TypedError> {
    let method = request
        .get("method")
        .and_then(Value::as_str)
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "Device USB request is missing method".to_owned(),
        })?;
    if method == "DeviceUsbProbe" {
        return dispatch_broker_usbip_probe(state, broker_caller_role_for_peer(peer));
    }

    let device_ref = request
        .get("resourceRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "Device USB request requires a Device resourceRef".to_owned(),
        })?;
    if device_ref.resource_type().as_str() != "Device" {
        return Err(TypedError::WireInvalidFrame {
            detail: "Device USB request resourceRef must name Device".to_owned(),
        });
    }
    let verb = match method {
        "DeviceUsbAttach" => "usb attach",
        "DeviceUsbDetach" => "usb detach",
        _ => {
            return Err(TypedError::WireUnsupportedRequest {
                request_type: method.to_owned(),
            });
        }
    };
    let runtime = resolve_resource_runtime(state, request).map_err(|_error| {
        TypedError::RuntimeCapabilityUnsupported {
            vm: device_ref.name().as_str().to_owned(),
            runtime_kind: "component-session".to_owned(),
            capability: "usbip-guest-import".to_owned(),
            verb: verb.to_owned(),
        }
    })?;
    let device = drive_sync(&state.runtime_handle, runtime.dispatch_public_cli_request(
        &json!({
            "method": "Get",
            "service": "d2b.resource.v3",
            "zoneRef": request.get("zoneRef").cloned().unwrap_or(Value::Null),
            "resourceRef": device_ref.to_canonical_string(),
        }),
        peer.uid,
    ))
    .map_err(|_| TypedError::RuntimeCapabilityUnsupported {
        vm: device_ref.name().as_str().to_owned(),
        runtime_kind: "component-session".to_owned(),
        capability: "usbip-guest-import".to_owned(),
        verb: verb.to_owned(),
    })?;
    if device
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|kind| kind == "error")
    {
        return Ok(device);
    }
    if device.pointer("/spec/providerRef").and_then(Value::as_str) != Some("Provider/device-usbip")
    {
        return Err(TypedError::RuntimeCapabilityUnsupported {
            vm: device_ref.name().as_str().to_owned(),
            runtime_kind: "component-session".to_owned(),
            capability: "usbip-guest-import".to_owned(),
            verb: verb.to_owned(),
        });
    }
    let owner_ref = device
        .pointer("/metadata/ownerRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|value| value.resource_type().as_str() == "Guest")
        .ok_or_else(|| TypedError::RuntimeCapabilityUnsupported {
            vm: device_ref.name().as_str().to_owned(),
            runtime_kind: "component-session".to_owned(),
            capability: "usbip-guest-import".to_owned(),
            verb: verb.to_owned(),
        })?;
    let bus_id = request
        .get("busId")
        .or_else(|| request.get("busid"))
        .and_then(Value::as_str)
        .ok_or_else(|| TypedError::WireInvalidFrame {
            detail: "Device USB request requires busId".to_owned(),
        })?;
    let mode = match mutation_mode_from_request(request, verb) {
        Ok(mode) => mode,
        Err(response) => return Ok(response),
    };
    let flags = public_wire::MutationFlags { mode, json: false };
    match method {
        "DeviceUsbAttach" => dispatch_broker_usbip_bind(
            state,
            broker_caller_role_for_peer(peer),
            public_wire::UsbipBindCliRequest {
                vm: owner_ref.name().as_str().to_owned(),
                bus_id: bus_id.to_owned(),
                flags,
            },
        ),
        "DeviceUsbDetach" => dispatch_broker_usbip_unbind(
            state,
            broker_caller_role_for_peer(peer),
            public_wire::UsbipUnbindCliRequest {
                vm: owner_ref.name().as_str().to_owned(),
                bus_id: bus_id.to_owned(),
                flags,
            },
        ),
        _ => unreachable!("closed Device USB method match"),
    }
}

/// Map a trusted-bundle Network spec parse failure onto the resource
/// runtime refusal surface, logging the manifest-parse-error reason.
fn network_intent_parse_error(
    error: d2b_contracts::error::Error,
) -> resource_runtime::ResourceRuntimeError {
    tracing::warn!(
        error = %error,
        "Network effect context could not resolve a trusted bundle intent"
    );
    resource_runtime::ResourceRuntimeError::ProviderPathUnavailable
}

pub(crate) fn resolve_network_effect_context(
    resource: &Value,
    resolver: &BundleResolver,
    admission: &NetworkAdmissionProof,
) -> Result<NetworkEffectContext, resource_runtime::ResourceRuntimeError> {
    let spec = resource
        .get("spec")
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    let provider_ref = spec
        .get("providerRef")
        .and_then(Value::as_str)
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    if provider_ref != "Provider/network-local" {
        return Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable);
    }
    let network_name = resource
        .get("metadata")
        .and_then(|metadata| metadata.get("name"))
        .and_then(Value::as_str)
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    let provenance = d2b_contracts_resource::v3::NetworkProvenance::new(
        admission.key().zone_uid().clone(),
        admission.key().network_uid().clone(),
        admission.key().network_generation(),
        admission.key().attachment_generation(),
        admission.key().bundle_generation().clone(),
    );
    let bridge_id = intent_id_network_bridge_uids(
        provenance.zone_uid(),
        provenance.network_uid(),
        network_name,
        false,
    );
    let uplink_bridge_id = intent_id_network_bridge_uids(
        provenance.zone_uid(),
        provenance.network_uid(),
        network_name,
        true,
    );
    let projection_id = intent_id_network_projection_uids(
        provenance.zone_uid(),
        provenance.network_uid(),
        network_name,
    );
    if resolver
        .resolve_network_bridge_intent(&bridge_id, &provenance)
        .map_err(network_intent_parse_error)?
        .is_none()
        || resolver
            .resolve_network_bridge_intent(&uplink_bridge_id, &provenance)
            .map_err(network_intent_parse_error)?
            .is_none()
    {
        return Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable);
    }
    let projection = resolver
        .resolve_network_projection_intent(&projection_id, &provenance)
        .map_err(network_intent_parse_error)?
        .ok_or(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable)?;
    let nm_id = intent_id_nm_unmanaged_host();
    if resolver.find_nm_unmanaged_intent(&nm_id).is_none() {
        return Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable);
    }
    let hosts_id = intent_id_network_hosts_uids(
        provenance.zone_uid(),
        provenance.network_uid(),
        network_name,
    );
    if resolver
        .resolve_network_hosts_intent(&hosts_id, &provenance)
        .map_err(network_intent_parse_error)?
        .is_none()
    {
        return Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable);
    }
    let route_ids = (0..admission.intent().routes().len())
        .map(|index| {
            BundleOpId::new(intent_id_network_route_uids(
                provenance.zone_uid(),
                provenance.network_uid(),
                network_name,
                index,
            ))
        })
        .collect::<Vec<_>>();
    for id in &route_ids {
        if resolver
            .resolve_network_route_intent(id.as_str(), &provenance)
            .map_err(network_intent_parse_error)?
            .is_none()
        {
            return Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable);
        }
    }
    let sysctl_ids = ["lan", "uplink"]
        .into_iter()
        .flat_map(|role| {
            let zone_uid = provenance.zone_uid().clone();
            let network_uid = provenance.network_uid().clone();
            let network_name = network_name.to_owned();
            ["disable-ipv6", "accept-ra", "autoconf"]
                .into_iter()
                .map(move |key| {
                    BundleOpId::new(intent_id_network_sysctl_uids(
                        &zone_uid,
                        &network_uid,
                        &network_name,
                        role,
                        key,
                    ))
                })
        })
        .collect::<Vec<_>>();
    for id in &sysctl_ids {
        if resolver
            .resolve_network_sysctl_intent(id.as_str(), &provenance)
            .map_err(network_intent_parse_error)?
            .is_none()
        {
            return Err(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable);
        }
    }
    let generation = resolver
        .installed_generation_identity()
        .and_then(|identity| ResourceBundleGenerationId::parse(identity.as_str().to_owned()).ok())
        .ok_or(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable)?;
    let projection_digest = projection_digest_bytes(&projection.script_body)
        .ok_or(resource_runtime::ResourceRuntimeError::ProviderPathUnavailable)?;
    let net_vm_name = derive_network_child_name(admission.key().network_uid(), "vm");
    Ok(NetworkEffectContext::for_network(
        admission.clone(),
        VmId::new(net_vm_name),
        BundleOpId::new(bridge_id),
        BundleOpId::new(projection_id),
        BundleOpId::new(nm_id),
        BundleOpId::new(hosts_id),
        route_ids,
        sysctl_ids,
        generation,
        projection_digest,
        resolver.host().site.allow_unsafe_east_west,
    )
    .with_additional_bridge_intent(BundleOpId::new(uplink_bridge_id)))
}

fn committed_resource_uid(
    resource: &Value,
) -> Result<ResourceUid, resource_runtime::ResourceRuntimeError> {
    resource
        .get("metadata")
        .and_then(|metadata| metadata.get("uid"))
        .and_then(Value::as_str)
        .and_then(|value| ResourceUid::parse(value.to_owned()).ok())
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)
}

fn committed_resource_generation(
    resource: &Value,
) -> Result<ResourceGeneration, resource_runtime::ResourceRuntimeError> {
    resource
        .get("metadata")
        .and_then(|metadata| metadata.get("generation"))
        .and_then(Value::as_u64)
        .and_then(|value| ResourceGeneration::new(value).ok())
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)
}

fn committed_resource_revision(
    resource: &Value,
) -> Result<ZoneRevision, resource_runtime::ResourceRuntimeError> {
    resource
        .get("metadata")
        .and_then(|metadata| metadata.get("revision"))
        .and_then(Value::as_u64)
        .filter(|value| *value != 0)
        .map(ZoneRevision::new)
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)
}

fn committed_zone_resource_identity(
    runtime: &resource_runtime::ZoneResourceRuntime,
    resource: &Value,
) -> Result<ZoneResourceIdentity, resource_runtime::ResourceRuntimeError> {
    let metadata = resource
        .get("metadata")
        .and_then(Value::as_object)
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    let resource_zone = metadata
        .get("zone")
        .and_then(Value::as_str)
        .and_then(|value| ZoneId::parse(value).ok())
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    if resource_zone != *runtime.zone() {
        return Err(resource_runtime::ResourceRuntimeError::RouteMismatch);
    }
    let resource_type = resource
        .get("type")
        .and_then(Value::as_str)
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    let resource_name = metadata
        .get("name")
        .and_then(Value::as_str)
        .ok_or(resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    let resource_ref_text = format!("{resource_type}/{resource_name}");
    let resource_ref = ResourceRef::parse(&resource_ref_text)
        .map_err(|_| resource_runtime::ResourceRuntimeError::RequestInvalid)?;
    let zone_uid = runtime
        .authority_zone_uid()
        .cloned()
        .ok_or(resource_runtime::ResourceRuntimeError::IdentityUnbound)?;
    Ok(ZoneResourceIdentity::new(
        resource_zone,
        zone_uid,
        resource_ref,
        committed_resource_uid(resource)?,
        committed_resource_generation(resource)?,
        committed_resource_revision(resource)?,
    ))
}

/// Resolve the committed execution resource for the same-UID unsafe-local
/// helper. The helper owns workload scopes, but the daemon may only bind them
/// to an identity read from the authoritative topology-root resource store.
fn authoritative_unsafe_local_resource_identity(
    state: &ServerState,
) -> Result<ZoneResourceIdentity, resource_runtime::ResourceRuntimeError> {
    let plane = state
        .resource_plane
        .try_lock()
        .ok()
        .and_then(|plane| plane.clone())
        .ok_or(resource_runtime::ResourceRuntimeError::PlaneUnavailable)?;
    let root_zone = plane
        .topology_root()
        .cloned()
        .ok_or(resource_runtime::ResourceRuntimeError::HandlerNotReady)?;
    let runtime = plane.zone(&root_zone)?;
    let hosts = drive_sync(&state.runtime_handle, runtime.committed_resources_of_type("Host"))?;
    let [host] = hosts.as_slice() else {
        return Err(resource_runtime::ResourceRuntimeError::RequestInvalid);
    };
    committed_zone_resource_identity(&runtime, host)
}

fn same_zone_resource_identity(left: &ZoneResourceIdentity, right: &ZoneResourceIdentity) -> bool {
    left.matches(
        right.zone(),
        right.zone_uid(),
        right.resource_ref(),
        right.resource_uid(),
        right.generation(),
        right.revision(),
    )
}

#[cfg(test)]
fn network_deletion_completed(resource: &Value) -> bool {
    resource
        .get("status")
        .and_then(|status| status.get("phase"))
        .and_then(Value::as_str)
        == Some("Deleted")
        && resource
            .get("metadata")
            .and_then(|metadata| metadata.get("finalizers"))
            .and_then(Value::as_array)
            .is_some_and(Vec::is_empty)
}

fn resolve_resource_runtime(
    state: &ServerState,
    request: &Value,
) -> Result<Arc<resource_runtime::ZoneResourceRuntime>, resource_runtime::ResourceRuntimeError> {
    let zone_ref = request.get("zoneRef").and_then(Value::as_str);
    let zone = zone_ref
        .and_then(|value| value.strip_prefix("Zone/"))
        .and_then(|value| ZoneId::parse(value.to_owned()).ok());
    let zone = match zone {
        Some(zone) => zone,
        None => {
            tracing::warn!(?zone_ref, "resource runtime Zone route parse failed");
            return Err(resource_runtime::ResourceRuntimeError::RouteMismatch);
        }
    };
    let plane = state
        .resource_plane
        .try_lock()
        .ok()
        .and_then(|plane| plane.clone())
        .ok_or(resource_runtime::ResourceRuntimeError::PlaneUnavailable)?;
    plane.zone(&zone).map_err(|error| {
        if error == resource_runtime::ResourceRuntimeError::PlaneUnavailable {
            resource_runtime::ResourceRuntimeError::RouteMismatch
        } else {
            error
        }
    })
}

fn resolve_typed_shell_runtime(
    state: &ServerState,
    request: &Value,
) -> Result<Arc<resource_runtime::ZoneResourceRuntime>, resource_runtime::ResourceRuntimeError> {
    let runtime = resolve_resource_runtime(state, request)?;
    let root = state
        .resource_plane
        .try_lock()
        .ok()
        .and_then(|plane| plane.clone())
        .and_then(|plane| plane.topology_root().cloned())
        .ok_or(resource_runtime::ResourceRuntimeError::HandlerNotReady)?;
    if runtime.zone() != &root {
        return Err(resource_runtime::ResourceRuntimeError::RouteMismatch);
    }
    Ok(runtime)
}

fn typed_shell_resource_request(request: &Value) -> bool {
    let shell_ref = request
        .get("resourceRef")
        .and_then(Value::as_str)
        .is_some_and(is_typed_shell_resource_ref);
    let shell_list = request.get("resourceType").and_then(Value::as_str)
        == Some("shell-terminal.d2bus.org.ShellSession");
    (shell_ref || shell_list)
        && matches!(
            request.get("method").and_then(Value::as_str),
            Some("List" | "Status" | "Detach" | "Kill")
        )
}

fn dispatch_typed_shell_resource_request(
    state: &ServerState,
    peer: &PeerIdentity,
    request: &Value,
) -> Result<Value, TypedError> {
    let method = request
        .get("method")
        .and_then(Value::as_str)
        .ok_or_else(shell_protocol_failed)?;
    let resource = request
        .get("resourceRef")
        .and_then(Value::as_str)
        .map(str::to_owned);
    if method == "List"
        && request
            .get("executionRef")
            .and_then(Value::as_str)
            .is_none()
    {
        return list_all_typed_shell_sessions(state, peer);
    }
    if method == "List" {
        let target = typed_shell_execution_target(
            request
                .get("executionRef")
                .and_then(Value::as_str)
                .ok_or_else(shell_protocol_failed)?,
        )?;
        return list_typed_shell_sessions_for_target(state, peer, &target);
    }
    let target = resolve_typed_shell_session_target(
        state,
        peer,
        resource.as_deref().ok_or_else(shell_protocol_failed)?,
    )?;
    let name = resource
        .as_deref()
        .map(typed_shell_resource_name)
        .transpose()?;
    let op = match method {
        "Status" => ShellManagementOp::List { target },
        "Detach" => ShellManagementOp::Detach {
            target,
            name: name.clone(),
        },
        "Kill" => ShellManagementOp::Kill {
            target,
            name: name.clone().ok_or_else(shell_protocol_failed)?,
        },
        _ => return Err(shell_protocol_failed()),
    };
    let result = dispatch_shell_management(state, peer, op)?;
    if method == "Status" {
        let name = name.ok_or_else(shell_protocol_failed)?;
        return result
            .get("sessions")
            .and_then(Value::as_array)
            .and_then(|sessions| {
                sessions.iter().find(|session| {
                    session.get("name").and_then(Value::as_str) == Some(name.as_str())
                })
            })
            .cloned()
            .ok_or_else(|| TypedError::WorkloadTargetNotFound {
                target: resource.unwrap_or_default(),
            });
    }
    Ok(result)
}

fn list_all_typed_shell_sessions(
    state: &ServerState,
    peer: &PeerIdentity,
) -> Result<Value, TypedError> {
    let listings = list_configured_typed_shell_targets(state, peer)?;
    let default_name = listings
        .first()
        .map(|(_, result)| result.default_name.clone())
        .unwrap_or_else(|| public_wire::ShellName::new("primary").expect("valid shell name"));
    let sessions = listings
        .into_iter()
        .flat_map(|(_, result)| result.sessions)
        .collect();
    serde_json::to_value(public_wire::ShellListResult {
        default_name,
        sessions,
    })
    .map_err(|_| shell_protocol_failed())
}

fn typed_shell_resource_error_frame(error: &TypedError) -> Value {
    use d2b_contracts_resource::v3::ResourceErrorKind;
    use d2bd_runtime::typed_error::ComponentSessionShellErrorKind as Guest;

    let kind = match error {
        TypedError::AuthzNotAdmin { .. } => ResourceErrorKind::AuthorizationDenied,
        TypedError::WorkloadTargetNotFound { .. }
        | TypedError::ComponentSessionShellFailed {
            kind: Guest::NotFound | Guest::StaleSession,
        } => ResourceErrorKind::ResourceNotFound,
        TypedError::ComponentSessionShellFailed {
            kind: Guest::Capability,
        }
        | TypedError::RuntimeCapabilityUnsupported { .. } => {
            ResourceErrorKind::UnsupportedCapability
        }
        TypedError::ComponentSessionShellFailed {
            kind: Guest::Transport,
        } => ResourceErrorKind::ResourceProviderUnavailable,
        TypedError::ComponentSessionShellFailed {
            kind: Guest::Timeout,
        } => ResourceErrorKind::Timeout,
        TypedError::ComponentSessionShellFailed {
            kind: Guest::Capacity,
        } => ResourceErrorKind::Backpressure,
        TypedError::ComponentSessionShellFailed {
            kind: Guest::AlreadyAttached,
        }
        | TypedError::WorkloadAliasConflict { .. } => ResourceErrorKind::ResourceConflict,
        _ => ResourceErrorKind::InternalIntegrityFailure,
    };
    json!({
        "type": "error",
        "error": {
            "kind": kind.as_str(),
            "errorClass": kind.as_str(),
            "retryClass": "never",
            "message": kind.as_str(),
            "remediation": "inspect the ShellSession Provider state and retry after its authoritative runtime is ready",
        }
    })
}

fn write_named_process_stream_error(
    stream: &Socket,
    request_id: u64,
    error: TypedError,
) -> Result<(), TypedError> {
    use d2bd_runtime::typed_error::ComponentSessionShellErrorKind as Guest;
    let kind = match &error {
        TypedError::AuthzNotAdmin { .. } => public_wire::NamedProcessStreamErrorKind::Authorization,
        TypedError::ComponentSessionShellFailed {
            kind: Guest::StaleSession,
        } => public_wire::NamedProcessStreamErrorKind::StaleSession,
        TypedError::ComponentSessionShellFailed {
            kind: Guest::NotFound,
        } => public_wire::NamedProcessStreamErrorKind::NotFound,
        TypedError::ComponentSessionShellFailed {
            kind: Guest::Capacity,
        } => public_wire::NamedProcessStreamErrorKind::Backpressure,
        TypedError::ComponentSessionShellFailed {
            kind: Guest::Timeout,
        } => public_wire::NamedProcessStreamErrorKind::Timeout,
        TypedError::ComponentSessionShellFailed {
            kind: Guest::Transport,
        } => public_wire::NamedProcessStreamErrorKind::Disconnected,
        _ => public_wire::NamedProcessStreamErrorKind::Protocol,
    };
    let response = public_wire::NamedProcessStreamResponseFrame::new(
        request_id,
        public_wire::NamedProcessStreamResponse::Error(public_wire::NamedProcessStreamError {
            kind,
        }),
    );
    write_json_frame(stream, &response)
}

fn dispatch_workload(
    state: &ServerState,
    peer: &PeerIdentity,
    op: public_wire::WorkloadOp,
) -> Result<Value, TypedError> {
    use workload_dispatch::{LaunchLedgerBegin, WorkloadCatalog, WorkloadRoute};

    if !matches!(peer.role, PeerRole::Launcher | PeerRole::Admin) {
        return Err(TypedError::AuthzNotALauncher { peer_uid: peer.uid });
    }
    let resolver = load_bundle_resolver(state)?;
    let realm_controllers = load_realm_controllers_config(&state.config.realm_controllers_config_path)
        .ok()
        .flatten();
    let catalog = WorkloadCatalog::from_resolver(
        &resolver,
        realm_controllers.as_ref().map(|loaded| &loaded.config),
    )
    .map_err(map_workload_catalog_error)?;
    let response = match op {
        public_wire::WorkloadOp::List(args) => {
            let observed = observe_workload_catalog(state, peer.uid, &catalog);
            record_workload_availability_metrics(&state.metrics_registry, &observed);
            let workloads = observed
                .iter()
                .filter(|entry| {
                    args.realm.as_ref().is_none_or(|realm| {
                        entry.entry.metadata.identity.realm_path.target_form() == *realm
                    })
                })
                .map(|observed| {
                    WorkloadCatalog::public_summary(
                        observed.entry,
                        observed.state,
                        observed.availability,
                    )
                })
                .collect();
            public_wire::WorkloadOpResponse::List(public_wire::WorkloadListResult { workloads })
        }
        public_wire::WorkloadOp::Status(args) => {
            let observed = observe_workload_catalog(state, peer.uid, &catalog);
            record_workload_availability_metrics(&state.metrics_registry, &observed);
            let observed = observed
                .into_iter()
                .find(|entry| entry.entry.metadata.identity.canonical_target == args.target)
                .ok_or_else(|| TypedError::WorkloadTargetNotFound {
                    target: args.target.to_canonical(),
                })?;
            public_wire::WorkloadOpResponse::Status(Box::new(public_wire::WorkloadStatusResult {
                workload: WorkloadCatalog::public_summary(
                    observed.entry,
                    observed.state,
                    observed.availability,
                ),
            }))
        }
        public_wire::WorkloadOp::LauncherExec(args) => {
            let route = catalog
                .resolve(&args.target)
                .map_err(|_| TypedError::WorkloadTargetNotFound {
                    target: args.target.to_canonical(),
                })?
                .route
                .clone();
            if let WorkloadRoute::CapabilityUnavailable { provider } = route {
                return Err(TypedError::RuntimeCapabilityUnsupported {
                    vm: args.target.to_canonical(),
                    runtime_kind: workload_provider_label(provider).to_owned(),
                    capability: "configured-launch".to_owned(),
                    verb: "launch".to_owned(),
                });
            }
            let (resolved, audit_context, begin) = prepare_workload_launch(
                state,
                peer.uid,
                &catalog,
                // The private unsafe-local exec artifact is v2-bundle-only; the
                // v3 emitter ships no unsafeLocalWorkloads artifact, so launcher
                // exec resolves from Realm launcher metadata alone (and refuses
                // with ArtifactsUnavailable when private argv is required).
                None,
                &args,
            )?;
            let operation_id = args.operation_id.to_string();
            if begin == LaunchLedgerBegin::AlreadyCommitted {
                record_workload_launch_result(
                    state,
                    peer.uid,
                    &audit_context,
                    &args.operation_id,
                    None,
                    WorkloadLaunchResult::AlreadyCommitted,
                )?;
                return Ok(d2bd_runtime::wire::workload_response(
                    &public_wire::WorkloadOpResponse::LauncherExec(
                        public_wire::LauncherExecResult {
                            target: args.target,
                            item_id: args.item_id,
                            operation_id: args.operation_id,
                            disposition: public_wire::LauncherExecDisposition::AlreadyCommitted,
                        },
                    ),
                ));
            }
            let dispatch_result = match &resolved.route {
                WorkloadRoute::UnsafeLocal => {
                    dispatch_unsafe_local_launcher(state, peer.uid, &args.operation_id, &resolved)
                        .map(|disposition| (disposition, None))
                }
                WorkloadRoute::LocalVm { vm } => {
                    dispatch_local_vm_launcher(state, peer.uid, vm, &args.operation_id, &resolved)
                }
                WorkloadRoute::CapabilityUnavailable { provider } => {
                    Err(TypedError::RuntimeCapabilityUnsupported {
                        vm: args.target.to_canonical(),
                        runtime_kind: workload_provider_label(*provider).to_owned(),
                        capability: "configured-launch".to_owned(),
                        verb: "launch".to_owned(),
                    })
                }
            };
            let (disposition, exec_id) = match dispatch_result {
                Ok(result) => result,
                Err(error) => {
                    workload_dispatch::abort_launch(peer.uid, &operation_id);
                    record_workload_launch_result(
                        state,
                        peer.uid,
                        &audit_context,
                        &args.operation_id,
                        None,
                        WorkloadLaunchResult::Failed,
                    )?;
                    return Err(error);
                }
            };
            workload_dispatch::complete_launch(peer.uid, &operation_id);
            let disposition = match disposition {
                public_wire::LauncherExecDisposition::Committed => {
                    record_workload_launch_result(
                        state,
                        peer.uid,
                        &audit_context,
                        &args.operation_id,
                        exec_id.as_deref(),
                        WorkloadLaunchResult::Committed,
                    )?;
                    public_wire::LauncherExecDisposition::Committed
                }
                public_wire::LauncherExecDisposition::AlreadyCommitted => {
                    record_workload_launch_result(
                        state,
                        peer.uid,
                        &audit_context,
                        &args.operation_id,
                        exec_id.as_deref(),
                        WorkloadLaunchResult::AlreadyCommitted,
                    )?;
                    public_wire::LauncherExecDisposition::AlreadyCommitted
                }
            };
            public_wire::WorkloadOpResponse::LauncherExec(public_wire::LauncherExecResult {
                target: args.target,
                item_id: args.item_id,
                operation_id: args.operation_id,
                disposition,
            })
        }
    };
    Ok(d2bd_runtime::wire::workload_response(&response))
}

fn prepare_workload_launch(
    state: &ServerState,
    requester_uid: u32,
    catalog: &workload_dispatch::WorkloadCatalog,
    private: Option<&d2b_contracts::unsafe_local_workloads::UnsafeLocalWorkloadsJson>,
    args: &public_wire::LauncherExecArgs,
) -> Result<
    (
        workload_dispatch::ResolvedExec,
        WorkloadLaunchAuditContext,
        workload_dispatch::LaunchLedgerBegin,
    ),
    TypedError,
> {
    let entry = catalog
        .resolve(&args.target)
        .map_err(|_| TypedError::WorkloadTargetNotFound {
            target: args.target.to_canonical(),
        })?;
    let audit_context = WorkloadLaunchAuditContext::from_entry(entry, &args.item_id);
    let resolved = match catalog.resolve_exec(private, &args.target, &args.item_id) {
        Ok(resolved) => resolved,
        Err(error) => {
            record_workload_launch_result(
                state,
                requester_uid,
                &audit_context,
                &args.operation_id,
                None,
                WorkloadLaunchResult::Refused,
            )?;
            return Err(map_workload_catalog_error(error));
        }
    };
    let begin = match workload_dispatch::begin_launch(
        requester_uid,
        &args.operation_id.to_string(),
        &args.target,
        &args.item_id,
    ) {
        Ok(begin) => begin,
        Err(error) => {
            record_workload_launch_result(
                state,
                requester_uid,
                &audit_context,
                &args.operation_id,
                None,
                WorkloadLaunchResult::Refused,
            )?;
            return Err(map_workload_catalog_error(error));
        }
    };
    Ok((resolved, audit_context, begin))
}

struct ObservedWorkload<'a> {
    entry: &'a workload_dispatch::CatalogEntry,
    state: d2b_contracts::WorkloadState,
    availability: public_wire::WorkloadAvailability,
}

fn observe_workload_catalog<'a>(
    state: &ServerState,
    requester_uid: u32,
    catalog: &'a workload_dispatch::WorkloadCatalog,
) -> Vec<ObservedWorkload<'a>> {
    catalog
        .entries()
        .map(|entry| {
            let (workload_state, availability) =
                workload_runtime_status(state, requester_uid, entry);
            ObservedWorkload {
                entry,
                state: workload_state,
                availability,
            }
        })
        .collect()
}

fn workload_runtime_status(
    state: &ServerState,
    requester_uid: u32,
    entry: &workload_dispatch::CatalogEntry,
) -> (
    d2b_contracts::WorkloadState,
    public_wire::WorkloadAvailability,
) {
    use d2b_contracts::WorkloadState;
    use d2b_contracts_control::unsafe_local_wire::HelperScopeState;
    use workload_dispatch::WorkloadRoute;

    match &entry.route {
        WorkloadRoute::UnsafeLocal => {
            let availability = unsafe_local_workload_availability(
                state.unsafe_local_helpers.availability(requester_uid),
                state
                    .unsafe_local_helpers
                    .last_failure(requester_uid, &entry.metadata.identity.canonical_target),
            );
            let authoritative_identity = authoritative_unsafe_local_resource_identity(state).ok();
            let workload_state = state
                .unsafe_local_helpers
                .snapshot(requester_uid)
                .and_then(|snapshot| {
                    let identity = authoritative_identity.as_ref()?;
                    snapshot
                        .scopes
                        .into_iter()
                        .find(|scope| same_zone_resource_identity(&scope.workload, identity))
                })
                .map_or(WorkloadState::Stopped, |scope| match scope.state {
                    HelperScopeState::Starting => WorkloadState::Starting,
                    HelperScopeState::Active => WorkloadState::Running,
                    HelperScopeState::Stopping => WorkloadState::Stopping,
                    HelperScopeState::Exited => WorkloadState::Stopped,
                    HelperScopeState::Degraded => WorkloadState::Failed,
                });
            (workload_state, availability)
        }
        WorkloadRoute::LocalVm { vm } => {
            let running = state
                .pidfd_table
                .list_for_vm(vm)
                .into_iter()
                .any(|registration| {
                    state
                        .pidfd_table
                        .still_alive_same_start_time(vm, &registration.role)
                });
            (
                if running {
                    WorkloadState::Running
                } else {
                    WorkloadState::Stopped
                },
                public_wire::WorkloadAvailability::Ready,
            )
        }
        WorkloadRoute::CapabilityUnavailable { .. } => (
            WorkloadState::Stopped,
            public_wire::WorkloadAvailability::Degraded,
        ),
    }
}

fn dispatch_unsafe_local_launcher(
    state: &ServerState,
    requester_uid: u32,
    operation_id: &d2b_contracts::OperationId,
    resolved: &workload_dispatch::ResolvedExec,
) -> Result<public_wire::LauncherExecDisposition, TypedError> {
    use d2b_contracts_control::unsafe_local_wire::{
        HelperLaunchRequest, HelperOperationDisposition,
    };
    let target = resolved.identity.canonical_target.clone();
    let workload = authoritative_unsafe_local_resource_identity(state).map_err(|_| {
        TypedError::RuntimeCapabilityUnsupported {
            vm: target.to_canonical(),
            runtime_kind: "unsafe-local".to_owned(),
            capability: "committed-resource-identity".to_owned(),
            verb: "launch".to_owned(),
        }
    })?;
    let request = HelperLaunchRequest {
        request_id: next_internal_helper_request_id(),
        operation_id: operation_id.clone(),
        workload,
        target,
        item_id: resolved.item_id.clone(),
        argv: resolved.argv.clone(),
        graphical: resolved.graphical,
        realm_accent_color: resolved.realm_accent_color.clone(),
    };
    let result = state
        .unsafe_local_helpers
        .dispatch_launch(requester_uid, request)
        .map_err(map_helper_registry_error)?;
    Ok(match result.disposition {
        HelperOperationDisposition::AlreadyCommitted => {
            public_wire::LauncherExecDisposition::AlreadyCommitted
        }
        HelperOperationDisposition::Committed | HelperOperationDisposition::Completed => {
            public_wire::LauncherExecDisposition::Committed
        }
    })
}

fn dispatch_local_vm_launcher(
    state: &ServerState,
    requester_uid: u32,
    vm: &str,
    operation_id: &d2b_contracts::OperationId,
    resolved: &workload_dispatch::ResolvedExec,
) -> Result<(public_wire::LauncherExecDisposition, Option<String>), TypedError> {
    ensure_vm_runtime_capability(state, vm, RuntimeCapabilityGate::Exec, "launch")?;
    let root_zone = state
        .resource_plane
        .try_lock()
        .ok()
        .and_then(|plane| plane.clone())
        .and_then(|plane| plane.topology_root().cloned())
        .ok_or_else(|| TypedError::RuntimeCapabilityUnsupported {
            vm: vm.to_owned(),
            runtime_kind: "resource-plane".to_owned(),
            capability: "committed-zone-topology".to_owned(),
            verb: "launch".to_owned(),
        })?;
    let mut fingerprint = Sha256::new();
    fingerprint.update(requester_uid.to_le_bytes());
    fingerprint.update(operation_id.as_str().as_bytes());
    fingerprint.update(resolved.identity.canonical_target.to_canonical().as_bytes());
    fingerprint.update(resolved.item_id.as_str().as_bytes());
    let request_id = format!(
        "workload-launch:{}",
        hex_bytes(&fingerprint.finalize()[..16])
    );
    let spec = exec_session::ExecStartSpec {
        vm: vm.to_owned(),
        request_id: Some(request_id.clone()),
        argv: resolved.argv.as_slice().to_vec(),
        tty: false,
        detached: true,
        env: Vec::new(),
        cwd: None,
        term_size: None,
    };
    let execution_ref = ResourceRef::parse(&format!("Guest/{vm}")).map_err(|_| {
        TypedError::RuntimeCapabilityUnsupported {
            vm: vm.to_owned(),
            runtime_kind: "component-session".to_owned(),
            capability: "process-create".to_owned(),
            verb: "launch".to_owned(),
        }
    })?;
    let resource_request = serde_json::json!({
        "zoneRef": format!("Zone/{}", root_zone.as_str()),
        "requestId": request_id,
    });
    let client = exec_detached::ResourceDetachedClient::new(
        production_process_resource_port(state, &resource_request, &execution_ref),
        execution_ref,
    )
    .map_err(|error| map_resource_exec_error(error, vm))?;
    let result = drive_sync(&state.runtime_handle, client.create(&spec))
        .map_err(|error| map_resource_exec_error(error, vm))?;
    emit_detached_create_audit(state, requester_uid, vm, &result.exec_id);
    Ok((
        public_wire::LauncherExecDisposition::Committed,
        Some(result.exec_id),
    ))
}

const WORKLOAD_PROVIDERS: [d2b_contracts::WorkloadProviderKind; 4] = [
    d2b_contracts::WorkloadProviderKind::LocalVm,
    d2b_contracts::WorkloadProviderKind::QemuMedia,
    d2b_contracts::WorkloadProviderKind::ProviderManaged,
    d2b_contracts::WorkloadProviderKind::UnsafeLocal,
];
const WORKLOAD_COMPONENTS: [&str; 5] = ["helper", "scope", "proxy", "launcher", "shell"];
const WORKLOAD_AVAILABILITY_STATES: [&str; 9] = [
    "ready",
    "helper-unavailable",
    "helper-stale",
    "user-manager-unavailable",
    "graphical-session-inactive",
    "wayland-unavailable",
    "proxy-unavailable",
    "degraded",
    "not-applicable",
];

fn record_workload_availability_metrics(
    registry: &d2bd_runtime::metrics::Registry,
    observed: &[ObservedWorkload<'_>],
) {
    let mut counts = BTreeMap::new();
    for provider in WORKLOAD_PROVIDERS {
        for component in WORKLOAD_COMPONENTS {
            for state in WORKLOAD_AVAILABILITY_STATES {
                counts.insert((workload_provider_label(provider), component, state), 0u64);
            }
        }
    }
    for observation in observed {
        let provider = workload_provider_label(observation.entry.metadata.provider_kind);
        let state_label = workload_availability_label(observation.availability);
        for component in WORKLOAD_COMPONENTS {
            let items = &observation.entry.metadata.items;
            let applicable = match component {
                "shell" => items
                    .iter()
                    .any(|item| item.kind == d2b_contracts::LauncherItemKind::Shell),
                "helper" | "scope" | "proxy" => provider == "unsafe-local",
                _ => true,
            };
            let selected = if applicable {
                state_label
            } else {
                "not-applicable"
            };
            *counts.entry((provider, component, selected)).or_insert(0) += 1;
        }
    }
    let samples = counts
        .into_iter()
        .map(|((provider, component, state), count)| {
            (
                vec![
                    ("provider", provider),
                    ("component", component),
                    ("state", state),
                ],
                count as f64,
            )
        })
        .collect::<Vec<_>>();
    registry.gauge_family_replace("d2b_daemon_workload_availability", &samples);
}

fn workload_lifecycle_metric(state: &ServerState, provider: &str, operation: &str, outcome: &str) {
    state.metrics_registry.counter_inc(
        "d2b_daemon_workload_lifecycle_total",
        &[
            ("provider", provider),
            ("operation", operation),
            ("outcome", outcome),
        ],
    );
}

#[derive(Debug)]
struct WorkloadLaunchAuditContext {
    target: String,
    item_id: String,
    provider_label: &'static str,
    audit_provider: d2bd_runtime::daemon_audit::WorkloadLaunchProvider,
}

impl WorkloadLaunchAuditContext {
    fn from_entry(
        entry: &workload_dispatch::CatalogEntry,
        requested_item: &d2b_contracts::ProtocolToken,
    ) -> Self {
        let (provider_label, audit_provider) = match entry.route {
            workload_dispatch::WorkloadRoute::LocalVm { .. } => (
                "local-vm",
                d2bd_runtime::daemon_audit::WorkloadLaunchProvider::LocalVm,
            ),
            workload_dispatch::WorkloadRoute::UnsafeLocal => (
                "unsafe-local",
                d2bd_runtime::daemon_audit::WorkloadLaunchProvider::UnsafeLocal,
            ),
            workload_dispatch::WorkloadRoute::CapabilityUnavailable { .. } => {
                unreachable!("unsupported routes reject before launch audit context")
            }
        };
        let item_id = entry
            .metadata
            .items
            .iter()
            .find(|item| item.id == *requested_item)
            .map_or_else(|| "unknown".to_owned(), |item| item.id.as_str().to_owned());
        Self {
            target: entry.metadata.identity.canonical_target.to_canonical(),
            item_id,
            provider_label,
            audit_provider,
        }
    }
}

#[derive(Clone, Copy)]
enum WorkloadLaunchResult {
    Committed,
    AlreadyCommitted,
    Refused,
    Failed,
}

fn record_workload_launch_result(
    state: &ServerState,
    peer_uid: u32,
    context: &WorkloadLaunchAuditContext,
    operation_id: &d2b_contracts::OperationId,
    exec_id: Option<&str>,
    result: WorkloadLaunchResult,
) -> Result<(), TypedError> {
    let (outcome, audit_result) = match result {
        WorkloadLaunchResult::Committed => (
            "committed",
            d2bd_runtime::daemon_audit::WorkloadLaunchResult::Committed,
        ),
        WorkloadLaunchResult::AlreadyCommitted => (
            "already-committed",
            d2bd_runtime::daemon_audit::WorkloadLaunchResult::AlreadyCommitted,
        ),
        WorkloadLaunchResult::Refused => (
            "refused",
            d2bd_runtime::daemon_audit::WorkloadLaunchResult::Refused,
        ),
        WorkloadLaunchResult::Failed => (
            "failed",
            d2bd_runtime::daemon_audit::WorkloadLaunchResult::Failed,
        ),
    };
    workload_lifecycle_metric(state, context.provider_label, "launcher-exec", outcome);
    state
        .daemon_audit
        .write_event_with_authority(
            d2bd_runtime::daemon_audit::DaemonEvent::WorkloadLauncher {
                target: context.target.clone(),
                item_id: context.item_id.clone(),
                operation_id: operation_id.to_string(),
                exec_id: exec_id.map(str::to_owned),
                peer_uid,
                provider: context.audit_provider,
                result: audit_result,
            },
            d2bd_runtime::daemon_audit::DaemonAuditAuthority::Authoritative,
        )
        .map_err(|_| TypedError::InternalIo {
            context: "authoritative workload audit".to_owned(),
            detail: "daemon audit unavailable".to_owned(),
            source: None,
        })
}

#[cfg(test)]
mod network_tap_provenance_tests {
    use super::*;
    use d2b_provider_network_local::controller::{NetworkAdmissionIntent, NetworkAdmissionKey};

    #[test]
    fn tap_context_copies_live_admission_tuple_and_all_interfaces() {
        let zone_uid = ResourceUid::parse("123e4567-e89b-42d3-a456-426614174000").unwrap();
        let network_uid = ResourceUid::parse("223e4567-e89b-42d3-a456-426614174001").unwrap();
        let first_guest = ResourceUid::parse("323e4567-e89b-42d3-a456-426614174002").unwrap();
        let second_guest = ResourceUid::parse("423e4567-e89b-42d3-a456-426614174003").unwrap();
        let bundle_generation = ResourceBundleGenerationId::parse(
            "sha256:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
        )
        .unwrap();
        let spec = d2b_contracts_resource::v3::network::NetworkSpec::minimal(
            d2b_contracts_resource::v3::network::Ipv4Cidr::parse("10.20.0.0/24").unwrap(),
            d2b_contracts_resource::v3::network::Ipv4Cidr::parse("192.0.2.0/30").unwrap(),
            d2b_contracts_resource::v3::execution_policy::BoundedToken::parse("net-vm-base")
                .unwrap(),
        )
        .unwrap();
        let proof = NetworkAdmissionIntent::new(
            NetworkAdmissionKey::new(
                zone_uid,
                network_uid,
                ResourceGeneration::new(4).unwrap(),
                ResourceGeneration::new(9).unwrap(),
                bundle_generation,
            ),
            spec,
            vec![first_guest.clone(), second_guest.clone()],
        )
        .unwrap()
        .proof();

        let first = network_tap_context_from_admission(&proof, first_guest);
        let second = network_tap_context_from_admission(&proof, second_guest);
        assert_eq!(first.zone_uid, second.zone_uid);
        assert_eq!(first.network_uid, second.network_uid);
        assert_eq!(
            first.network_generation,
            ResourceGeneration::new(4).unwrap()
        );
        assert_eq!(
            first.attachment_generation,
            ResourceGeneration::new(9).unwrap()
        );
        assert_eq!(
            first.admitted_interface_names,
            proof.intent().interface_names()
        );
        assert_ne!(first.attachment_id, second.attachment_id);
        assert_eq!(
            second.admitted_interface_names,
            proof.intent().interface_names()
        );
    }

    #[test]
    fn network_admission_release_requires_deleted_resource_without_finalizers() {
        assert!(!network_deletion_completed(&json!({
            "type": "ZoneLink",
            "metadata": {"finalizers": ["network.d2bus.org/cleanup"]},
            "status": {"phase": "Deleted"}
        })));
        assert!(!network_deletion_completed(&json!({
            "metadata": {"finalizers": []},
            "status": {"phase": "Ready"}
        })));
        assert!(network_deletion_completed(&json!({
            "metadata": {"finalizers": []},
            "status": {"phase": "Deleted"}
        })));
    }
}

