    #[test]
    fn dispatch_status_read_model_is_cached_and_pidfd_invalidated() {
        let root = tempfile::tempdir().expect("artifact root");
        let artifacts = write_public_status_artifacts(root.path());
        let (state, _dir) = test_state_with_config(DaemonConfig {
            artifacts,
            ..DaemonConfig::default()
        });
        let request = public_wire::StatusRequest {
            check_bridges: false,
            vm: None,
        };

        let first = dispatch_status_as(&state, BrokerCallerRole::NotAuthorized, request.clone()).expect("first status dispatch");
        let first_generation = first
            .pointer("/status/readModel/generation")
            .and_then(Value::as_u64)
            .expect("first read-model generation");
        assert_eq!(
            first
                .pointer("/status/entries/0/lifecycle/state")
                .and_then(Value::as_str),
            Some("Stopped")
        );

        let second = dispatch_status_as(&state, BrokerCallerRole::NotAuthorized, request.clone()).expect("cached status dispatch");
        assert_eq!(
            second
                .pointer("/status/readModel/generation")
                .and_then(Value::as_u64),
            Some(first_generation),
            "unchanged artifacts and runtime generation should reuse the published read model"
        );

        state
            .pidfd_table
            .register(
                "vm-a".to_owned(),
                VM_RUNNER_ROLE_ID.to_owned(),
                current_process_entry(),
            )
            .expect("register ch runner");
        let refreshed = dispatch_status_as(&state, BrokerCallerRole::NotAuthorized, request).expect("refreshed status dispatch");
        assert!(
            refreshed
                .pointer("/status/readModel/generation")
                .and_then(Value::as_u64)
                .is_some_and(|generation| generation > first_generation),
            "pidfd generation changes must invalidate the cached read model"
        );
        assert_eq!(
            refreshed
                .pointer("/status/entries/0/lifecycle/state")
                .and_then(Value::as_str),
            Some("Running")
        );
    }

    #[test]
    fn status_read_model_refuses_to_cache_when_fingerprint_changes_during_build() {
        let root = tempfile::tempdir().expect("artifact root");
        let artifacts = write_public_status_artifacts(root.path());
        let (state, _dir) = test_state_with_config(DaemonConfig {
            artifacts,
            ..DaemonConfig::default()
        });
        let before = public_artifact_fingerprint(&state).expect("before fingerprint");
        let stale_frame = d2bd_runtime::wire::status_response(json!({
            "entries": [{
                "vm": "vm-a",
                "name": "vm-a",
                "lifecycle": { "state": "Stopped" }
            }]
        }));

        state
            .pidfd_table
            .register(
                "vm-a".to_owned(),
                VM_RUNNER_ROLE_ID.to_owned(),
                current_process_entry(),
            )
            .expect("register ch runner");
        let returned = publish_public_frame_if_stable(
            &state,
            PublicReadModelKind::Status,
            Some(before),
            stale_frame.clone(),
        );

        assert_eq!(returned, stale_frame);
        assert!(
            state
                .public_status_read_model
                .load_status(state.pidfd_table.generation())
                .is_none(),
            "stale pre-mutation frame must not be cached under the post-mutation fingerprint"
        );
    }

    #[test]
    fn dispatch_list_and_status_without_filters_preserve_all_vm_order() {
        let root = tempfile::tempdir().expect("artifact root");
        let artifacts = write_public_status_artifacts(root.path());
        let (state, _dir) = test_state_with_config(DaemonConfig {
            artifacts,
            ..DaemonConfig::default()
        });
        state
            .pidfd_table
            .register(
                "vm-b".to_owned(),
                VM_RUNNER_ROLE_ID.to_owned(),
                current_process_entry(),
            )
            .expect("register vm-b runner");

        let list = dispatch_list(
            &state,
            public_wire::ListRequest {
                env: None,
                vm: None,
            },
        )
        .expect("unfiltered list dispatch");
        let list_names = list
            .get("vms")
            .and_then(Value::as_array)
            .expect("list vms")
            .iter()
            .map(|entry| {
                entry
                    .get("vm")
                    .and_then(Value::as_str)
                    .expect("list vm name")
                    .to_owned()
            })
            .collect::<Vec<_>>();
        assert_eq!(list_names, vec!["vm-a", "vm-b"]);
        // v2 closures-artifact contract removed: no synthesis for v3
        // Zone-native fixtures without Guest package refs.
        assert!(
            !list.pointer("/vms/0/guestClosureOutPath").is_some_and(Value::is_string),
            "v3 list must not synthesize a v2 closure-out-path"
        );
        assert!(
            !list.pointer("/vms/1/guestClosureOutPath").is_some_and(Value::is_string),
            "v3 list must not synthesize a v2 closure-out-path"
        );
        assert_eq!(
            list.pointer("/vms/1/lifecycle/state")
                .and_then(Value::as_str),
            Some("Running")
        );

        let status = dispatch_status_as(
            &state,
            BrokerCallerRole::NotAuthorized,
            public_wire::StatusRequest {
                check_bridges: false,
                vm: None,
            },
        )
        .expect("unfiltered status dispatch");
        let status_names = status
            .pointer("/status/entries")
            .and_then(Value::as_array)
            .expect("status entries")
            .iter()
            .map(|entry| {
                entry
                    .get("vm")
                    .and_then(Value::as_str)
                    .expect("status vm name")
                    .to_owned()
            })
            .collect::<Vec<_>>();
        assert_eq!(status_names, vec!["vm-a", "vm-b"]);
        assert_eq!(
            status
                .pointer("/status/entries/1/lifecycle/state")
                .and_then(Value::as_str),
            Some("Running")
        );
    }

