    /// Wiring test: verify that `ServerState.daemon_audit` is wired with a
    /// `DaemonAuditLog` that can capture `DaemonEvent::ApiReadyTimeout`
    /// events, and that the event serialises with the expected field shape.
    ///
    /// This complements the deeper unit tests in `d2bd_runtime::daemon_audit::tests` by
    /// asserting that the `ServerState` construction and the `DaemonEvent` fields
    /// match what `dispatch_broker_vm_start` actually writes at the timeout site.
    #[test]
    #[allow(clippy::disallowed_methods, reason = "cfg(test) helper")]
    fn api_ready_timeout_audit_event_captured_via_server_state() {
        let dir = tempfile::tempdir().expect("create temp dir");
        let broker_reap_log = BrokerReapLog::new();
        let state_dir = dir.path().to_path_buf();
        let state = ServerState {
            config: DaemonConfig::default(),
            daemon_uid: 0,
            daemon_audit: Arc::new(d2bd_runtime::daemon_audit::DaemonAuditLog::new(&state_dir)),
            daemon_state_dir: state_dir.clone(),
            pidfd_table: Arc::new(
                PidfdTable::new(state_dir.join("pidfd-table.json"))
                    .with_broker_reap_log(Arc::clone(&broker_reap_log)),
            ),
            broker_reap_log,
            metrics_registry: Arc::new(d2bd_runtime::metrics::Registry::new()),
            exec_sessions: Arc::new(crate::exec_session::SessionTable::new(
                crate::exec_session::ExecSessionCaps::default(),
            )),
            console_sessions: Arc::new(tokio::sync::Mutex::new(
                crate::console_session::ConsoleSessionTable::default(),
            )),
            conn_semaphore: d2bd_runtime::concurrency::ConnSemaphore::new(8),
            op_locks: d2bd_runtime::concurrency::OpLockManager::new(),
            public_status_read_model: Arc::new(
                d2bd_runtime::public_read_model::PublicStatusReadModel::new(),
            ),
            provider_runtime: Arc::new(crate::provider_registry::ProviderRuntime::new()),
            resource_plane: Arc::new(tokio::sync::Mutex::new(None)),
            interaction_runtime: Arc::new(tokio::sync::Mutex::new(None)),
            interaction_listeners: Arc::new(tokio::sync::Mutex::new(None)),
            typed_shell_session_targets: d2bd_runtime::typed_shell_targets::new_cache(),
            zone_coordinator: d2bd_runtime::zone_authority::new_coordinator(),
            config_staging: Arc::new(tokio::sync::Mutex::new(Default::default())),
            guest_component_sessions: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
            guest_component_session_locks: Arc::new(tokio::sync::Mutex::new(HashMap::new())),
            security_key_sessions: Arc::new(tokio::sync::Mutex::new(
                d2b_provider_device_security_key::SkSessionTable::default(),
            )),
            unsafe_local_helpers: Arc::new(d2bd_runtime::unsafe_local_helper::HelperRegistry::new(
                0,
                [],
            )),
            v3_planes: std::sync::Arc::new(tokio::sync::Mutex::new(HashMap::new())),
        runtime_handle: test_runtime_handle(),
        };

        // Emit the same event that the timeout handler in
        // dispatch_broker_vm_start writes.
        state
            .daemon_audit
            .write_event(
                d2bd_runtime::daemon_audit::DaemonEvent::ApiReadyTimeout {
                vm: "vm-a".to_owned(),
                runner: VM_RUNNER_ROLE_ID.to_owned(),
                elapsed_secs: 120,
                mode: d2bd_runtime::daemon_audit::ApiReadyMode::Strict,
            })
            .expect("write ApiReadyTimeout audit event");

        let captured = state
            .daemon_audit
            .captured()
            .lock()
            .expect("lock captured records");
        assert_eq!(
            captured.len(),
            1,
            "expected exactly one captured audit record"
        );
        let record: serde_json::Value =
            serde_json::from_str(&captured[0]).expect("parse captured record as JSON");
        let event = record.get("event").expect("event field must be present");
        assert_eq!(
            event.get("kind").and_then(|v| v.as_str()),
            Some("api_ready_timeout"),
            "event.kind must be 'api_ready_timeout'",
        );
        assert_eq!(
            event.get("vm").and_then(|v| v.as_str()),
            Some(
                d2b_contracts_resource::v3::canonical_digest(
                    "d2b:daemon-audit-redaction:v1",
                    b"vm-a",
                )
                .as_str(),
            ),
        );
        assert_eq!(
            event.get("runner").and_then(|v| v.as_str()),
            Some(VM_RUNNER_ROLE_ID),
        );
        assert_eq!(
            event.get("elapsed_secs").and_then(|v| v.as_u64()),
            Some(120),
        );
        assert_eq!(event.get("mode").and_then(|v| v.as_str()), Some("strict"),);
    }

